 ) as s(pos,code,kind,parent_code,title_es,title_en,unit_es,unit_en,vat_code,markup_bp)
$$;
create or replace function public.pro_cost_code_line_figures(p_planned bigint,p_markup_bp integer,p_vat text)
returns table(markup bigint,sale bigint,tax bigint)
language sql immutable security invoker set search_path=public,pg_temp as $$
 with m as(select round(coalesce(p_planned,0)::numeric*coalesce(p_markup_bp,0)/10000)::bigint markup)
 select m.markup,coalesce(p_planned,0)+m.markup,round((coalesce(p_planned,0)+m.markup)::numeric*public.pro_cost_code_vat_rate(p_vat)/100)::bigint from m
$$;
create or replace function public.pro_cost_code_forecast_figures(p_planned bigint,p_markup bigint,p_sale bigint,p_tax bigint,
 p_committed bigint,p_actual bigint,p_unknown bigint,p_projected bigint,p_eac bigint) returns jsonb
language sql immutable security invoker set search_path=public,pg_temp as $$
 select jsonb_build_object('costCents',p_planned,'markupCents',p_markup,'saleCents',p_sale,'taxCents',p_tax,'totalCents',p_sale+p_tax,
  'committedCents',p_committed,'actualCents',p_actual,'unknownCount',p_unknown,'projectedCents',p_projected,
  'remainingCents',p_eac-p_projected,'eacCents',p_eac,
  'varianceCents',case when p_unknown>0 then null else p_planned-p_eac end,
  'consumedBp',case when p_planned>0 then (p_actual*10000/p_planned) else null end,
  'status',case when p_unknown>0 then 'incomplete' when p_planned=0 and p_eac=0 then 'idle' when p_eac>p_planned then 'over'
   when p_projected*10>=p_planned*9 then 'watch' else 'ok' end)
$$;

-- ===== Library =====
create or replace function public.pro_cost_codes_read(p_actor uuid,p_query jsonb) returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare v text;st text;lang text;items jsonb;rev integer;
begin
 if not coalesce(public.pro_private_work_tools_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;
 if jsonb_typeof(p_query) is distinct from 'object' or exists(select 1 from jsonb_object_keys(p_query) k where k not in('view','status','lang'))
  or jsonb_typeof(p_query->'view') is distinct from 'string' then raise exception 'Invalid cost code query' using errcode='22023';end if;
 v:=p_query->>'view';st:=coalesce(p_query->>'status','active');lang:=coalesce(p_query->>'lang','es');
 if v not in('library','starter') or st not in('active','archived','all') or lang not in('es','en') then raise exception 'Invalid cost code query' using errcode='22023';end if;
 rev:=coalesce((select revision from public.pro_cost_code_library_state where owner_id=p_actor),0);
 if v='starter' then
  select coalesce(jsonb_agg(jsonb_build_object('code',s.code,'kind',s.kind,'parentCode',s.parent_code,
    'title',case when lang='en' then s.title_en else s.title_es end,'unit',case when lang='en' then s.unit_en else s.unit_es end,
    'vatCode',s.vat_code,'markupBp',s.markup_bp,'exists',exists(select 1 from public.pro_cost_code_library l where l.owner_id=p_actor and l.code=s.code)) order by s.pos),'[]'::jsonb)
   into items from public.pro_cost_code_starter() s;
  return jsonb_build_object('revision',rev,'lang',lang,'items',items);
 end if;
 select coalesce(jsonb_agg(public.pro_cost_code_json(c)||jsonb_build_object('parentCode',p.code,'parentTitle',p.title,
   'usage',(select count(*) from public.pro_work_budget_line_settings s where s.owner_id=p_actor and s.library_id=c.id))
   order by coalesce(p.code,c.code),c.parent_id is not null,c.code),'[]'::jsonb) into items
  from public.pro_cost_code_library c left join public.pro_cost_code_library p on p.owner_id=c.owner_id and p.id=c.parent_id
  where c.owner_id=p_actor and(st='all' or c.archived=(st='archived'));
 return jsonb_build_object('revision',rev,'status',st,'items',items,
  'activeCount',(select count(*) from public.pro_cost_code_library where owner_id=p_actor and not archived),
  'archivedCount',(select count(*) from public.pro_cost_code_library where owner_id=p_actor and archived),
  'capacity',500);
end $$;

create or replace function public.pro_cost_codes_mutate(p_actor uuid,p_input jsonb) returns jsonb
language plpgsql security invoker set search_path=public,pg_temp as $$
declare act text;aid uuid;rev integer;cur integer;keys text[];receipt public.pro_cost_code_actions;r public.pro_cost_code_library;
 cid uuid;pid uuid;created integer:=0;linked integer:=0;skipped integer:=0;lang text;wanted text[];srow record;wrow record;
 lib_id uuid;wid text;result jsonb;code_json jsonb;v_unit text;v_vat text;v_markup integer;ctx jsonb;
begin
 if not coalesce(public.pro_private_work_tools_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;
 if jsonb_typeof(p_input) is distinct from 'object' or jsonb_typeof(p_input->'action') is distinct from 'string'
  or jsonb_typeof(p_input->'actionId') is distinct from 'string' or jsonb_typeof(p_input->'revision') is distinct from 'number'
  or not coalesce(p_input->>'revision' ~ '^[0-9]{1,10}$',false) or(p_input->>'revision')::numeric>2147483646 then
  raise exception 'Invalid cost code mutation' using errcode='22023';end if;
 act:=p_input->>'action';aid:=(p_input->>'actionId')::uuid;rev:=(p_input->>'revision')::integer;
 keys:=array['action','actionId','revision']||case act when 'save' then array['id','kind','code','title','parentId','unit','vatCode','markupBp']
  when 'archive' then array['id'] when 'restore' then array['id'] when 'import_starter' then array['lang','codes'] when 'import_work' then array['workId'] else null end;
 if keys is null or not(p_input ?& keys) or(p_input-keys)<>'{}'::jsonb then raise exception 'Invalid cost code fields' using errcode='22023';end if;
 perform pg_advisory_xact_lock(hashtextextended('pro-cost-codes-action:'||p_actor::text||':'||aid::text,0));
 perform pg_advisory_xact_lock(hashtextextended('pro-cost-codes:'||p_actor::text,0));
 select * into receipt from public.pro_cost_code_actions where owner_id=p_actor and action_id=aid;
 if found then
  if receipt.input is distinct from p_input then raise exception 'Cost code action reused' using errcode='40001';end if;
  return receipt.result;
 end if;
 select revision into cur from public.pro_cost_code_library_state where owner_id=p_actor for update;
 if coalesce(cur,0)<>rev then raise exception 'Cost code library changed' using errcode='40001';end if;
 if act='save' then
  if jsonb_typeof(p_input->'id') is distinct from 'string' or jsonb_typeof(p_input->'kind') is distinct from 'string' or p_input->>'kind' not in('group','item')
   or jsonb_typeof(p_input->'code') is distinct from 'string' or not coalesce(p_input->>'code' ~ '^[A-Z0-9][A-Z0-9._-]{0,29}$',false)
   or jsonb_typeof(p_input->'title') is distinct from 'string' or length(btrim(p_input->>'title')) not between 1 and 160 or p_input->>'title' ~ '[[:cntrl:]]'
   or jsonb_typeof(p_input->'parentId') not in('null','string') or jsonb_typeof(p_input->'unit') not in('null','string')
   or jsonb_typeof(p_input->'vatCode') not in('null','string') or jsonb_typeof(p_input->'markupBp') not in('null','number') then
   raise exception 'Invalid cost code content' using errcode='22023';end if;
  cid:=(p_input->>'id')::uuid;pid:=(p_input->>'parentId')::uuid;
  v_unit:=nullif(btrim(p_input->>'unit'),'');v_vat:=p_input->>'vatCode';
  if jsonb_typeof(p_input->'markupBp')='number' then
   if not coalesce(p_input->>'markupBp' ~ '^[0-9]{1,6}$',false) or(p_input->>'markupBp')::integer>100000 then raise exception 'Invalid markup' using errcode='22023';end if;
   v_markup:=(p_input->>'markupBp')::integer;
  end if;
  if p_input->>'kind'='group' and(pid is not null or v_unit is not null or v_vat is not null or v_markup is not null) then raise exception 'Groups only have code and name' using errcode='22023';end if;
  if v_vat is not null and v_vat not in('01','02','03','04','08','09','10','11') then raise exception 'Invalid VAT tariff' using errcode='22023';end if;
  if v_unit is not null and(length(v_unit)>20 or v_unit ~ '[[:cntrl:]]') then raise exception 'Invalid unit' using errcode='22023';end if;
  select * into r from public.pro_cost_code_library where owner_id=p_actor and id=cid for update;
  if found and(r.archived or r.kind<>p_input->>'kind') then raise exception 'Restore code or retain its kind' using errcode='40001';end if;
  if not found and(select count(*) from public.pro_cost_code_library where owner_id=p_actor)>=500 then raise exception 'Cost code capacity reached' using errcode='54000';end if;
  if pid is not null and not exists(select 1 from public.pro_cost_code_library where owner_id=p_actor and id=pid and kind='group' and not archived) then
   raise exception 'Choose an active group' using errcode='40001';end if;
  insert into public.pro_cost_code_library(owner_id,id,kind,code,title,parent_id,unit,vat_code,markup_bp)
   values(p_actor,cid,p_input->>'kind',p_input->>'code',btrim(p_input->>'title'),pid,v_unit,v_vat,v_markup)
   on conflict(owner_id,id) do update set code=excluded.code,title=excluded.title,parent_id=excluded.parent_id,unit=excluded.unit,
    vat_code=excluded.vat_code,markup_bp=excluded.markup_bp,updated_at=clock_timestamp()
   returning * into r;
  code_json:=public.pro_cost_code_json(r);
 elsif act in('archive','restore') then
  if jsonb_typeof(p_input->'id') is distinct from 'string' then raise exception 'Invalid cost code identity' using errcode='22023';end if;
  cid:=(p_input->>'id')::uuid;
  select * into r from public.pro_cost_code_library where owner_id=p_actor and id=cid for update;
  if not found then raise exception 'Cost code unavailable' using errcode='P0002';end if;
  if r.archived=(act='archive') then raise exception 'Cost code status changed' using errcode='40001';end if;
  if act='archive' and r.kind='group' and exists(select 1 from public.pro_cost_code_library where owner_id=p_actor and parent_id=cid and not archived) then
   raise exception 'Archive active children first' using errcode='40001';end if;
  if act='restore' and r.parent_id is not null and not exists(select 1 from public.pro_cost_code_library where owner_id=p_actor and id=r.parent_id and not archived) then
   raise exception 'Restore parent group first' using errcode='40001';end if;
  update public.pro_cost_code_library set archived=(act='archive'),updated_at=clock_timestamp() where owner_id=p_actor and id=cid returning * into r;
  code_json:=public.pro_cost_code_json(r);
 elsif act='import_starter' then
  lang:=p_input->>'lang';
  if lang is null or lang not in('es','en') or jsonb_typeof(p_input->'codes') is distinct from 'array'
   or jsonb_array_length(p_input->'codes') not between 1 and 100
   or exists(select 1 from jsonb_array_elements(p_input->'codes') e where jsonb_typeof(e) is distinct from 'string')
   or exists(select 1 from jsonb_array_elements_text(p_input->'codes') e where e not in(select code from public.pro_cost_code_starter()))
   or(select count(distinct e) from jsonb_array_elements_text(p_input->'codes') e)<>jsonb_array_length(p_input->'codes') then
   raise exception 'Invalid starter selection' using errcode='22023';end if;
  select array_agg(e) into wanted from jsonb_array_elements_text(p_input->'codes') e;
  -- A chosen item brings its group.
  wanted:=wanted||coalesce((select array_agg(distinct s2.parent_code) from public.pro_cost_code_starter() s2 where s2.code=any(wanted) and s2.parent_code is not null),array[]::text[]);
  for srow in select * from public.pro_cost_code_starter() st where st.code=any(wanted) order by st.kind='item',st.pos loop
   if exists(select 1 from public.pro_cost_code_library where owner_id=p_actor and code=srow.code) then skipped:=skipped+1;continue;end if;
   if(select count(*) from public.pro_cost_code_library where owner_id=p_actor)>=500 then raise exception 'Cost code capacity reached' using errcode='54000';end if;
   pid:=null;
   if srow.parent_code is not null then select id into pid from public.pro_cost_code_library where owner_id=p_actor and code=srow.parent_code and kind='group' and not archived;end if;
   insert into public.pro_cost_code_library(owner_id,id,kind,code,title,parent_id,unit,vat_code,markup_bp,source)
    values(p_actor,public.pro_cost_code_uuid('starter:'||aid::text||':'||srow.code),srow.kind,srow.code,case when lang='en' then srow.title_en else srow.title_es end,pid,
     case when lang='en' then srow.unit_en else srow.unit_es end,srow.vat_code,srow.markup_bp,'starter');
   created:=created+1;
  end loop;
 else -- import_work: copy the per-work codes of one project into the library and link them.
  if jsonb_typeof(p_input->'workId') is distinct from 'string' or length(p_input->>'workId') not between 1 and 160 then raise exception 'Invalid work' using errcode='22023';end if;
  wid:=p_input->>'workId';ctx:=public.pro_work_budget_context(p_actor,wid);
  perform pg_advisory_xact_lock(hashtextextended('pro-work-budget:'||p_actor::text||':'||wid,0));
  if not exists(select 1 from public.pro_work_budget_codes where owner_id=p_actor and work_id=wid and not archived) then
   raise exception 'The work has no active budget codes' using errcode='40001';end if;
  for wrow in select c.*,ls.library_id,ls.markup_bp lm,ls.vat_code lv,p.code parent_code from public.pro_work_budget_codes c
    left join public.pro_work_budget_line_settings ls on ls.owner_id=c.owner_id and ls.work_id=c.work_id and ls.code_id=c.id
    left join public.pro_work_budget_codes p on p.owner_id=c.owner_id and p.work_id=c.work_id and p.id=c.parent_id
    where c.owner_id=p_actor and c.work_id=wid and not c.archived order by c.kind='item',c.code loop
   select id into lib_id from public.pro_cost_code_library where owner_id=p_actor and code=wrow.code and kind=wrow.kind;
   if lib_id is null then
    if exists(select 1 from public.pro_cost_code_library where owner_id=p_actor and code=wrow.code) then skipped:=skipped+1;continue;end if;
    if(select count(*) from public.pro_cost_code_library where owner_id=p_actor)>=500 then raise exception 'Cost code capacity reached' using errcode='54000';end if;
    pid:=null;
    if wrow.parent_code is not null then select id into pid from public.pro_cost_code_library where owner_id=p_actor and code=wrow.parent_code and kind='group' and not archived;end if;
    lib_id:=public.pro_cost_code_uuid('work:'||aid::text||':'||wrow.id::text);
    insert into public.pro_cost_code_library(owner_id,id,kind,code,title,parent_id,unit,vat_code,markup_bp,source)
     values(p_actor,lib_id,wrow.kind,wrow.code,wrow.title,pid,null,case when wrow.kind='item' then wrow.lv end,case when wrow.kind='item' then wrow.lm end,'work');
    created:=created+1;
   else linked:=linked+1;end if;
   insert into public.pro_work_budget_line_settings(owner_id,work_id,code_id,library_id) values(p_actor,wid,wrow.id,lib_id)
    on conflict(owner_id,work_id,code_id) do update set library_id=coalesce(public.pro_work_budget_line_settings.library_id,excluded.library_id);
  end loop;
  insert into public.pro_work_budget_extra_state values(p_actor,wid,1) on conflict(owner_id,work_id) do update set revision=public.pro_work_budget_extra_state.revision+1;
 end if;
 if cur is null then insert into public.pro_cost_code_library_state values(p_actor,1);
 else update public.pro_cost_code_library_state set revision=revision+1 where owner_id=p_actor;end if;
 result:=jsonb_build_object('action',act,'revision',rev+1,'code',code_json,'created',created,'linked',linked,'skipped',skipped);
 insert into public.pro_cost_code_actions(owner_id,action_id,scope,work_id,input,result) values(p_actor,aid,'library',null,p_input,result);
 return result;
end $$;

-- ===== Forecast (owner) =====
create or replace function public.pro_cost_code_forecast_rows(p_owner uuid,p_work text)
returns table(id uuid,kind text,code text,title text,parent_id uuid,archived boolean,library_id uuid,library_code text,markup_bp integer,vat_code text,
 planned bigint,committed bigint,actual bigint,unknown bigint)
language sql stable security invoker set search_path=public,pg_temp as $$
 with sources as materialized(select * from public.pro_work_budget_sources(p_owner,p_work)),
 committed as materialized(select l.budget_code_id code_id,sum(l.subtotal_cents+l.tax_cents)::bigint cents
   from public.pro_purchase_order_lines l join public.pro_purchase_orders o on o.owner_id=l.owner_id and o.id=l.order_id
   where l.owner_id=p_owner and l.work_id=p_work and o.status<>'cancelled' and l.budget_code_id is not null group by l.budget_code_id)
 select c.id,c.kind,c.code,c.title,c.parent_id,c.archived,s.library_id,lib.code,s.markup_bp,s.vat_code,
  c.planned_cents,coalesce(m.cents,0)::bigint,
  coalesce((select sum(x.amount_cents) from sources x where x.code_id=c.id),0)::bigint,
  (select count(*) from sources x where x.code_id=c.id and x.amount_cents is null)::bigint
 from public.pro_work_budget_codes c
 left join public.pro_work_budget_line_settings s on s.owner_id=c.owner_id and s.work_id=c.work_id and s.code_id=c.id
 left join public.pro_cost_code_library lib on lib.owner_id=s.owner_id and lib.id=s.library_id
 left join committed m on m.code_id=c.id
 where c.owner_id=p_owner and c.work_id=p_work
$$;

-- Client-visible summary: active groups and sale totals only (never cost, markup, committed or actual).
create or replace function public.pro_cost_code_client_snapshot(p_owner uuid,p_work text) returns jsonb
language sql stable security invoker set search_path=public,pg_temp as $$
 with codes as materialized(select * from public.pro_work_budget_codes where owner_id=p_owner and work_id=p_work),
 items as materialized(select i.id,i.parent_id,f.sale,f.tax from codes i
   left join public.pro_work_budget_line_settings s on s.owner_id=i.owner_id and s.work_id=i.work_id and s.code_id=i.id
   cross join lateral public.pro_cost_code_line_figures(i.planned_cents,s.markup_bp,s.vat_code) f
   where i.kind='item' and not i.archived and(i.parent_id is null or exists(select 1 from codes g where g.id=i.parent_id and not g.archived))),
 groups as(select g.code,g.title,sum(i.sale)::bigint sale from codes g join items i on i.parent_id=g.id group by g.id,g.code,g.title)
 select jsonb_build_object('title',(select service from public.pro_work where user_id=p_owner and id=p_work),'currency','CRC',
  'groups',coalesce((select jsonb_agg(jsonb_build_object('code',code,'title',title,'saleCents',sale) order by code) from groups),'[]'::jsonb),
  'otherSaleCents',(select sum(sale)::bigint from items where parent_id is null),
  'lineCount',(select count(*) from items),
  'saleCents',coalesce((select sum(sale) from items),0)::bigint,'taxCents',coalesce((select sum(tax) from items),0)::bigint,
  'totalCents',coalesce((select sum(sale+tax) from items),0)::bigint)
$$;

create or replace function public.pro_cost_code_forecast_read(p_actor uuid,p_work text) returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare ctx jsonb;rows jsonb;totals jsonb;loose record;share_row public.pro_work_budget_client_shares;current_snapshot jsonb;hist jsonb;customer text;
begin
 if p_work is null or length(p_work) not between 1 and 160 then raise exception 'Invalid forecast query' using errcode='22023';end if;
 ctx:=public.pro_work_budget_context(p_actor,p_work);
 with r as materialized(select * from public.pro_cost_code_forecast_rows(p_actor,p_work)),
 items as materialized(select r.*,f.markup,f.sale,f.tax,greatest(r.committed,r.actual) projected,greatest(r.planned,greatest(r.committed,r.actual)) eac
   from r cross join lateral public.pro_cost_code_line_figures(r.planned,r.markup_bp,r.vat_code) f where r.kind='item'),
 grouped as(select g.id,g.kind,g.code,g.title,g.parent_id,g.archived,g.library_id,g.library_code,null::integer markup_bp,null::text vat_code,
   coalesce(sum(i.planned),0)::bigint planned,coalesce(sum(i.markup),0)::bigint markup,coalesce(sum(i.sale),0)::bigint sale,coalesce(sum(i.tax),0)::bigint tax,
   coalesce(sum(i.committed),0)::bigint committed,coalesce(sum(i.actual),0)::bigint actual,coalesce(sum(i.unknown),0)::bigint unknown,
   coalesce(sum(i.projected),0)::bigint projected,coalesce(sum(i.eac),0)::bigint eac,count(i.id) children
   from r g left join items i on i.parent_id=g.id where g.kind='group' group by g.id,g.kind,g.code,g.title,g.parent_id,g.archived,g.library_id,g.library_code),
 every as(select id,kind,code,title,parent_id,archived,library_id,library_code,markup_bp,vat_code,planned,markup,sale,tax,committed,actual,unknown,projected,eac,null::bigint children from items
   union all select * from grouped)
 select coalesce(jsonb_agg(jsonb_build_object('codeId',e.id,'kind',e.kind,'code',e.code,'title',e.title,'parentId',e.parent_id,'archived',e.archived,
   'libraryId',e.library_id,'libraryCode',e.library_code,'markupBp',e.markup_bp,'vatCode',e.vat_code,'childCount',e.children)
   ||public.pro_cost_code_forecast_figures(e.planned,e.markup,e.sale,e.tax,e.committed,e.actual,e.unknown,e.projected,e.eac)
   order by coalesce((select p.code from r p where p.id=e.parent_id),e.code),e.parent_id is not null,e.code),'[]'::jsonb) into rows from every e;
 select coalesce((select sum(l.subtotal_cents+l.tax_cents) from public.pro_purchase_order_lines l join public.pro_purchase_orders o on o.owner_id=l.owner_id and o.id=l.order_id
   where l.owner_id=p_actor and l.work_id=p_work and o.status<>'cancelled' and l.budget_code_id is null),0)::bigint committed,
  coalesce((select sum(s.amount_cents) from public.pro_work_budget_sources(p_actor,p_work) s where s.code_id is null),0)::bigint actual,
  (select count(*) from public.pro_work_budget_sources(p_actor,p_work) s where s.code_id is null and s.amount_cents is null)::bigint unknown
  into loose;
 with r as materialized(select * from public.pro_cost_code_forecast_rows(p_actor,p_work) where kind='item'),
 items as(select r.*,f.markup,f.sale,f.tax,greatest(r.committed,r.actual) projected,greatest(r.planned,greatest(r.committed,r.actual)) eac
   from r cross join lateral public.pro_cost_code_line_figures(r.planned,r.markup_bp,r.vat_code) f)
 select public.pro_cost_code_forecast_figures(coalesce(sum(planned),0)::bigint,coalesce(sum(markup),0)::bigint,coalesce(sum(sale),0)::bigint,coalesce(sum(tax),0)::bigint,
   coalesce(sum(committed),0)::bigint+loose.committed,coalesce(sum(actual),0)::bigint+loose.actual,coalesce(sum(unknown),0)::bigint+loose.unknown,
   coalesce(sum(projected),0)::bigint+greatest(loose.committed,loose.actual),coalesce(sum(eac),0)::bigint+greatest(loose.committed,loose.actual))
  ||jsonb_build_object('itemCount',count(*),'pricedCount',count(*) filter(where markup_bp is not null or vat_code is not null),
   'overCount',count(*) filter(where unknown=0 and eac>planned),'watchCount',count(*) filter(where unknown=0 and eac<=planned and planned>0 and projected*10>=planned*9))
  into totals from items;
 select * into share_row from public.pro_work_budget_client_shares where owner_id=p_actor and work_id=p_work and revoked_at is null;
 current_snapshot:=public.pro_cost_code_client_snapshot(p_actor,p_work);
 select coalesce(jsonb_agg(jsonb_build_object('id',x.id,'sharedAt',x.shared_at,'revokedAt',x.revoked_at,'reason',x.revoked_reason,'totalCents',(x.snapshot->>'totalCents')::bigint) order by x.shared_at desc,x.id),'[]'::jsonb)
  into hist from(select * from public.pro_work_budget_client_shares where owner_id=p_actor and work_id=p_work order by shared_at desc,id limit 10) x;
 select ar.client_name into customer from public.pro_appointment_requests ar join public.profiles c on c.id=ar.client_user_id
  where ar.owner_id=p_actor and ar.work_id=p_work and ar.status in('confirmed','completed') and not coalesce(c.is_disabled,false)
  order by ar.updated_at desc,ar.id desc limit 1;
 return jsonb_build_object('work',jsonb_build_object('id',ctx->>'id','clientId',ctx->>'clientId','title',ctx->>'title'),
  'currency','CRC','canWrite',not(ctx->>'cancelled')::boolean and not(ctx->>'clientArchived')::boolean,
  'budgetRevision',coalesce((select revision from public.pro_work_budget_state where owner_id=p_actor and work_id=p_work),0),
  'revision',coalesce((select revision from public.pro_work_budget_extra_state where owner_id=p_actor and work_id=p_work),0),
  'rows',rows,'totals',totals||jsonb_build_object('uncoded',jsonb_build_object('committedCents',loose.committed,'actualCents',loose.actual,'unknownCount',loose.unknown,
   'projectedCents',greatest(loose.committed,loose.actual))),
  'clientPreview',current_snapshot,
  'share',case when share_row.id is null then null else jsonb_build_object('id',share_row.id,'sharedAt',share_row.shared_at,'snapshot',share_row.snapshot,
   'stale',share_row.snapshot is distinct from current_snapshot) end,
  'shareHistory',hist,'customerName',customer);
end $$;

create or replace function public.pro_cost_code_extras_mutate(p_actor uuid,p_input jsonb) returns jsonb
language plpgsql security invoker set search_path=public,pg_temp as $$
declare act text;aid uuid;wid text;rev integer;cur integer;keys text[];receipt public.pro_cost_code_actions;ctx jsonb;brev integer;
 ids uuid[];lib record;work_code public.pro_work_budget_codes;new_id uuid;mapped jsonb:='{}'::jsonb;created integer:=0;linked integer:=0;skipped integer:=0;
 v_vat text;v_markup integer;result jsonb;snapshot jsonb;share_id uuid;active public.pro_work_budget_client_shares;n integer;
begin
 if not coalesce(public.pro_private_work_tools_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;
 if jsonb_typeof(p_input) is distinct from 'object' or jsonb_typeof(p_input->'action') is distinct from 'string'
  or jsonb_typeof(p_input->'actionId') is distinct from 'string' or jsonb_typeof(p_input->'workId') is distinct from 'string'
  or jsonb_typeof(p_input->'revision') is distinct from 'number' or not coalesce(p_input->>'revision' ~ '^[0-9]{1,10}$',false)
  or(p_input->>'revision')::numeric>2147483646 or length(p_input->>'workId') not between 1 and 160 then
  raise exception 'Invalid budget extras mutation' using errcode='22023';end if;
 act:=p_input->>'action';aid:=(p_input->>'actionId')::uuid;wid:=p_input->>'workId';rev:=(p_input->>'revision')::integer;
 keys:=array['action','actionId','workId','revision']||case act when 'price' then array['codeIds','markupBp','vatCode']
  when 'apply_library' then array['budgetRevision','libraryIds'] when 'share' then array[]::text[] when 'revoke' then array['shareId'] else null end;
 if keys is null or not(p_input ?& keys) or(p_input-keys)<>'{}'::jsonb then raise exception 'Invalid budget extras fields' using errcode='22023';end if;
 perform pg_advisory_xact_lock(hashtextextended('pro-cost-codes-action:'||p_actor::text||':'||aid::text,0));
 perform pg_advisory_xact_lock(hashtextextended('pro-work-budget:'||p_actor::text||':'||wid,0));
 ctx:=public.pro_work_budget_context(p_actor,wid);
 select * into receipt from public.pro_cost_code_actions where owner_id=p_actor and action_id=aid;
 if found then
  if receipt.input is distinct from p_input then raise exception 'Budget extras action reused' using errcode='40001';end if;
  return receipt.result;
 end if;
 if(ctx->>'cancelled')::boolean or(ctx->>'clientArchived')::boolean then raise exception 'Restore work or customer before changing budget' using errcode='40001';end if;
 select revision into cur from public.pro_work_budget_extra_state where owner_id=p_actor and work_id=wid for update;
 if coalesce(cur,0)<>rev then raise exception 'Budget extras changed' using errcode='40001';end if;
 if act in('price','apply_library') then
  if jsonb_typeof(p_input->case when act='price' then 'codeIds' else 'libraryIds' end) is distinct from 'array' then raise exception 'Invalid identities' using errcode='22023';end if;
  if exists(select 1 from jsonb_array_elements(p_input->case when act='price' then 'codeIds' else 'libraryIds' end) e where jsonb_typeof(e) is distinct from 'string') then raise exception 'Invalid identities' using errcode='22023';end if;
  select array_agg(e::uuid) into ids from jsonb_array_elements_text(p_input->case when act='price' then 'codeIds' else 'libraryIds' end) e;
  if coalesce(array_length(ids,1),0) not between 1 and 500 or(select count(distinct x) from unnest(ids) x)<>array_length(ids,1) then raise exception 'Invalid identities' using errcode='22023';end if;
 end if;
 if act='price' then
  if jsonb_typeof(p_input->'markupBp') is distinct from 'number' or not coalesce(p_input->>'markupBp' ~ '^[0-9]{1,6}$',false) or(p_input->>'markupBp')::integer>100000
   or jsonb_typeof(p_input->'vatCode') not in('null','string') or(p_input->>'vatCode' is not null and p_input->>'vatCode' not in('01','02','03','04','08','09','10','11')) then
   raise exception 'Invalid markup or VAT' using errcode='22023';end if;
  v_markup:=(p_input->>'markupBp')::integer;v_vat:=p_input->>'vatCode';
  select count(*) into n from public.pro_work_budget_codes where owner_id=p_actor and work_id=wid and id=any(ids) and kind='item' and not archived;
  if n<>array_length(ids,1) then raise exception 'Choose active budget items' using errcode='40001';end if;
  insert into public.pro_work_budget_line_settings(owner_id,work_id,code_id,markup_bp,vat_code) select p_actor,wid,x,v_markup,v_vat from unnest(ids) x
   on conflict(owner_id,work_id,code_id) do update set markup_bp=excluded.markup_bp,vat_code=excluded.vat_code;
  linked:=n;
 elsif act='apply_library' then
  if jsonb_typeof(p_input->'budgetRevision') is distinct from 'number' or not coalesce(p_input->>'budgetRevision' ~ '^[0-9]{1,10}$',false) then raise exception 'Invalid budget revision' using errcode='22023';end if;
  brev:=coalesce((select revision from public.pro_work_budget_state where owner_id=p_actor and work_id=wid),0);
  if brev<>(p_input->>'budgetRevision')::bigint then raise exception 'Budget changed' using errcode='40001';end if;
  select count(*) into n from public.pro_cost_code_library where owner_id=p_actor and id=any(ids) and not archived;
  if n<>array_length(ids,1) then raise exception 'Library changed' using errcode='40001';end if;
  -- A chosen item that will be created brings its active group (a linked item keeps its current group).
  ids:=ids||coalesce((select array_agg(distinct l.parent_id) from public.pro_cost_code_library l where l.owner_id=p_actor and l.id=any(ids) and l.parent_id is not null
   and not exists(select 1 from public.pro_work_budget_codes wc where wc.owner_id=p_actor and wc.work_id=wid and wc.code=l.code)
   and exists(select 1 from public.pro_cost_code_library g where g.owner_id=p_actor and g.id=l.parent_id and not g.archived) and not(l.parent_id=any(ids))),array[]::uuid[]);
  for lib in select * from public.pro_cost_code_library l where l.owner_id=p_actor and l.id=any(ids) order by l.kind='item',l.code loop
   select * into work_code from public.pro_work_budget_codes where owner_id=p_actor and work_id=wid and code=lib.code;
   if found then
    if work_code.kind<>lib.kind or work_code.archived then skipped:=skipped+1;continue;end if;
    -- Existing per-work code with the same code: map it, keep its planned amount and pricing.
    insert into public.pro_work_budget_line_settings(owner_id,work_id,code_id,library_id,markup_bp,vat_code)
     values(p_actor,wid,work_code.id,lib.id,lib.markup_bp,lib.vat_code)
     on conflict(owner_id,work_id,code_id) do update set library_id=coalesce(public.pro_work_budget_line_settings.library_id,excluded.library_id);
    mapped:=mapped||jsonb_build_object(lib.id::text,work_code.id);linked:=linked+1;continue;
   end if;
   new_id:=public.pro_cost_code_uuid('budget-code:'||p_actor::text||':'||aid::text||':'||lib.id::text);
   perform public.pro_work_budget_mutate(p_actor,case when lib.kind='group' then
     jsonb_build_object('action','save_group','actionId',public.pro_cost_code_uuid('budget-action:'||aid::text||':'||lib.id::text),'workId',wid,'clientId',ctx->>'clientId','revision',brev,'id',new_id,'code',lib.code,'title',lib.title)
    else jsonb_build_object('action','save_item','actionId',public.pro_cost_code_uuid('budget-action:'||aid::text||':'||lib.id::text),'workId',wid,'clientId',ctx->>'clientId','revision',brev,'id',new_id,'code',lib.code,'title',lib.title,
     'parentId',case when lib.parent_id is not null and mapped ? lib.parent_id::text then mapped->lib.parent_id::text else 'null'::jsonb end,'plannedCents',0) end);
   brev:=brev+1;
   insert into public.pro_work_budget_line_settings(owner_id,work_id,code_id,library_id,markup_bp,vat_code) values(p_actor,wid,new_id,lib.id,lib.markup_bp,lib.vat_code);
   mapped:=mapped||jsonb_build_object(lib.id::text,new_id);created:=created+1;
  end loop;
 elsif act='share' then
  snapshot:=public.pro_cost_code_client_snapshot(p_actor,wid);
  if(snapshot->>'lineCount')::integer=0 then raise exception 'Nothing to share' using errcode='40001';end if;
  update public.pro_work_budget_client_shares set revoked_at=clock_timestamp(),revoked_reason='replaced' where owner_id=p_actor and work_id=wid and revoked_at is null;
  share_id:=public.pro_cost_code_uuid('budget-share:'||p_actor::text||':'||aid::text);
  insert into public.pro_work_budget_client_shares(owner_id,work_id,id,snapshot) values(p_actor,wid,share_id,snapshot);
 else -- revoke
  if jsonb_typeof(p_input->'shareId') is distinct from 'string' then raise exception 'Invalid share' using errcode='22023';end if;
  select * into active from public.pro_work_budget_client_shares where owner_id=p_actor and work_id=wid and revoked_at is null for update;
  if active.id is null or active.id<>(p_input->>'shareId')::uuid then raise exception 'Share changed' using errcode='40001';end if;
  update public.pro_work_budget_client_shares set revoked_at=clock_timestamp(),revoked_reason='revoked' where owner_id=p_actor and id=active.id;
  share_id:=active.id;
 end if;
 if not exists(select 1 from public.pro_work_budget_state where owner_id=p_actor and work_id=wid) then raise exception 'Create budget codes first' using errcode='40001';end if;
 if cur is null then insert into public.pro_work_budget_extra_state values(p_actor,wid,1);
 else update public.pro_work_budget_extra_state set revision=revision+1 where owner_id=p_actor and work_id=wid;end if;
 result:=jsonb_build_object('action',act,'workId',wid,'revision',rev+1,
  'budgetRevision',coalesce((select revision from public.pro_work_budget_state where owner_id=p_actor and work_id=wid),0),
  'created',created,'linked',linked,'skipped',skipped,'shareId',share_id);
 insert into public.pro_cost_code_actions(owner_id,action_id,scope,work_id,input,result) values(p_actor,aid,'work',wid,p_input,result);
 ctx:=public.pro_work_budget_context(p_actor,wid);
 if(ctx->>'cancelled')::boolean or(ctx->>'clientArchived')::boolean then raise exception 'Work or customer changed' using errcode='40001';end if;
 return result;
end $$;

-- ===== Customer reader =====
create or replace function public.pro_cost_code_client_read(p_actor uuid,p_request uuid) returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare owner uuid;wid text;req_status text;s public.pro_work_budget_client_shares;
begin
 if not exists(select 1 from public.profiles where id=p_actor and not coalesce(is_disabled,false)) then raise exception 'Forbidden' using errcode='42501';end if;
 if p_request is null then raise exception 'Invalid budget summary query' using errcode='22023';end if;
 select owner_id,work_id,status into owner,wid,req_status from public.pro_appointment_requests where id=p_request and client_user_id=p_actor and work_id is not null;
 if not found then return null;end if;
 if req_status not in('confirmed','completed') then return jsonb_build_object('visible',false);end if;
 select * into s from public.pro_work_budget_client_shares where owner_id=owner and work_id=wid and revoked_at is null;
 if s.id is null then return jsonb_build_object('visible',false);end if;
 return jsonb_build_object('visible',true,'sharedAt',s.shared_at,'title',s.snapshot->'title','currency','CRC','groups',s.snapshot->'groups',
  'otherSaleCents',s.snapshot->'otherSaleCents','saleCents',s.snapshot->'saleCents','taxCents',s.snapshot->'taxCents','totalCents',s.snapshot->'totalCents');
end $$;

-- ===== Integrity =====
create or replace function public.pro_cost_code_action_immutable() returns trigger
language plpgsql security invoker set search_path=public,pg_temp as $$
begin
 if tg_op='DELETE' and not exists(select 1 from public.profiles where id=old.owner_id) then return old;end if;
 raise exception 'Immutable cost code receipt' using errcode='23514';
end $$;
create or replace function public.pro_cost_code_share_guard() returns trigger
language plpgsql security invoker set search_path=public,pg_temp as $$
begin
 if tg_op='DELETE' then
  if not exists(select 1 from public.profiles where id=old.owner_id) or not exists(select 1 from public.pro_work_budget_state where owner_id=old.owner_id and work_id=old.work_id) then return old;end if;
  raise exception 'Shared budget summaries are kept' using errcode='23514';
 end if;
 -- Only one transition: active -> revoked/replaced. The shared snapshot never changes.
 if old.revoked_at is not null or new.revoked_at is null or(new.owner_id,new.work_id,new.id,new.snapshot,new.shared_at) is distinct from(old.owner_id,old.work_id,old.id,old.snapshot,old.shared_at) then
  raise exception 'Shared budget summary is immutable' using errcode='23514';end if;
 return new;
end $$;
drop trigger if exists pro_cost_code_action_immutable on public.pro_cost_code_actions;
create trigger pro_cost_code_action_immutable before update or delete on public.pro_cost_code_actions for each row execute function public.pro_cost_code_action_immutable();
drop trigger if exists pro_cost_code_share_guard on public.pro_work_budget_client_shares;
create trigger pro_cost_code_share_guard before update or delete on public.pro_work_budget_client_shares for each row execute function public.pro_cost_code_share_guard();

do $$declare t text;f record;begin
 foreach t in array array['pro_cost_code_library_state','pro_cost_code_library','pro_work_budget_line_settings','pro_work_budget_extra_state','pro_work_budget_client_shares','pro_cost_code_actions'] loop
  execute format('alter table public.%I enable row level security',t);
  execute format('revoke all on public.%I from public,anon,authenticated',t);
  execute format('grant all on public.%I to service_role',t);
 end loop;
 for f in select p.oid::regprocedure signature from pg_proc p join pg_namespace n on n.oid=p.pronamespace
  where n.nspname='public' and p.proname like 'pro_cost_code%' loop
  execute format('revoke all on function %s from public,anon,authenticated',f.signature);
  execute format('grant execute on function %s to service_role',f.signature);
 end loop;
end $$;
commit;
notify pgrst,'reload schema';

-- ===== work-file-mentions-local.sql =====
-- LOCAL PRO ONLY. Registro de paridad, fila 30: «@menciones del equipo» en los comentarios
-- privados ('team') de un archivo del trabajo, con un buzón interno aislado. NO sends/outbox:
-- no e-mail, push, notifications or notification_push_outbox rows (pro_notifications and its
-- event CHECK are untouched).
-- Builds on file-versions-local.sql WITHOUT altering it: the comment itself is created by the
-- established writer pro_work_file_versions_mutate (same receipts, limits, locks and checks),
-- called from pro_work_file_comment_with_mentions in the SAME transaction, which then records
-- the explicit mentions. A comment never exists half-mentioned.
-- Model
--  * Only the job owner writes the team thread (file-versions-local.sql), so recipients are the
--    active collaborators of THAT job (pro_team_grants: owner_id, work_id, active), captured
--    with their grant id and generation (source_invite_id). Revoking access (or a new
--    invitation generation) hides the notice; nothing is deleted.
--  * 1..10 recipients per comment, each named in the body as "@"+name (case-insensitive), no
--    duplicates, never the author. Mentions and receipts are immutable; editing the comment
--    later does not add, remove or resend mentions.
--  * The member has NO access to job files: a notice stores only job service, file name,
--    version number, author name, an excerpt (<= 280) and the date. No file id, object path,
--    URL or bytes are ever returned to the member. A notice is hidden while its comment is
--    archived or the owner loses Pro tools, and disappears with the file (cascade).
-- Pattern: closed RLS + revoke, security invoker RPCs for service_role only, owner eligibility
-- pro_private_work_tools_enabled, idempotent receipts per actionId (same id + other payload ->
-- 22023), target changes -> 40001, Costa Rica dates (dayCr). Reapplicable; only new objects.
-- Lock order: mention action advisory -> (writer) wfv action advisory -> 'pro-work-files:<owner>:<work>'
-- -> family -> grant rows.
begin;
create table if not exists public.pro_work_file_comment_mentions(
 owner_id uuid not null,work_id text not null,comment_id uuid not null,recipient_id uuid not null,
 name text not null check(length(name) between 1 and 160),recipient_grant_id uuid not null,recipient_source_invite_id uuid not null,
 created_at timestamptz not null default clock_timestamp(),primary key(comment_id,recipient_id),
 foreign key(owner_id,comment_id) references public.pro_work_file_comments(owner_id,id) on delete cascade
);
create index if not exists pro_work_file_comment_mentions_owner on public.pro_work_file_comment_mentions(owner_id,comment_id);
create table if not exists public.pro_work_file_mention_actions(
 actor_id uuid not null references public.profiles(id) on delete cascade,action_id uuid not null,
 owner_id uuid not null,comment_id uuid not null,input jsonb not null,result jsonb not null,at timestamptz not null default clock_timestamp(),
 primary key(actor_id,action_id),foreign key(owner_id,comment_id) references public.pro_work_file_comments(owner_id,id) on delete cascade
);
create table if not exists public.pro_work_file_mention_notices(
 id uuid primary key default gen_random_uuid(),recipient_id uuid not null,owner_id uuid not null,work_id text not null,
 comment_id uuid not null,actor_id uuid not null,actor_name text not null check(length(actor_name)<=160),
 recipient_grant_id uuid not null,recipient_source_invite_id uuid not null,
 service text not null check(length(service)<=160),file_name text not null check(length(file_name) between 1 and 160),
 version_no smallint check(version_no between 1 and 100),excerpt text not null check(length(excerpt) between 1 and 280),
 created_at timestamptz not null default clock_timestamp(),read_at timestamptz,
 unique(comment_id,recipient_id),
 foreign key(owner_id,comment_id) references public.pro_work_file_comments(owner_id,id) on delete cascade,
 foreign key(owner_id,work_id) references public.pro_work(user_id,id) on delete cascade
);
create index if not exists pro_work_file_mention_notices_page on public.pro_work_file_mention_notices(recipient_id,created_at desc,id desc);
create table if not exists public.pro_work_file_mention_notice_actions(
 actor_id uuid not null references public.profiles(id) on delete cascade,action_id uuid not null,
 notice_id uuid not null references public.pro_work_file_mention_notices(id) on delete cascade,input jsonb not null,result jsonb not null,
 at timestamptz not null default clock_timestamp(),primary key(actor_id,action_id)
);

-- ===================================================================== helpers
-- Display name of a collaborator: the captured grant name, else the profile name ('' = not mentionable).
create or replace function public.pro_wfm_member_name(p_grant public.pro_team_grants) returns text
language sql stable security invoker set search_path=public,pg_temp as $$
 select coalesce(nullif(left(btrim(p_grant.member_name),160),''),nullif(public.pro_team_name(p_grant.member_user_id),''),'');
$$;
-- Active, enabled collaborators of one job (never the actor), ordered by name.
create or replace function public.pro_work_file_mention_targets(p_actor uuid,p_work text) returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare items jsonb;
begin
 if not coalesce(public.pro_private_work_tools_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;
 if p_work is null or length(p_work) not between 1 and 160 or not exists(select 1 from public.pro_work where user_id=p_actor and id=p_work) then raise exception 'Forbidden' using errcode='42501';end if;
 select coalesce(jsonb_agg(jsonb_build_object('userId',x.member_user_id,'grantId',x.id,'sourceInviteId',x.source_invite_id,'name',x.name) order by lower(x.name),x.member_user_id),'[]'::jsonb) into items from(
  select g.member_user_id,g.id,g.source_invite_id,public.pro_wfm_member_name(g) name from public.pro_team_grants g join public.profiles p on p.id=g.member_user_id
  where g.owner_id=p_actor and g.work_id=p_work and g.active and not coalesce(p.is_disabled,false) and g.member_user_id<>p_actor and public.pro_wfm_member_name(g)<>''
  order by lower(public.pro_wfm_member_name(g)),g.member_user_id limit 100) x;
 return jsonb_build_object('workId',p_work,'items',items);
end $$;
create or replace function public.pro_wfm_mentions_json(p_comment uuid) returns jsonb
language sql stable security invoker set search_path=public,pg_temp as $$
 select coalesce(jsonb_agg(jsonb_build_object('userId',m.recipient_id,'name',m.name) order by lower(m.name),m.recipient_id),'[]'::jsonb) from public.pro_work_file_comment_mentions m where m.comment_id=p_comment;
$$;

-- ===================================================================== write
-- Input: the exact comment_create of pro_work_file_versions_mutate (thread 'team') + mentions[1..10]
-- of {userId,grantId,sourceInviteId} taken from pro_work_file_mention_targets.
create or replace function public.pro_work_file_comment_with_mentions(p_actor uuid,p_input jsonb) returns jsonb
language plpgsql security invoker set search_path=public,pg_temp as $$
declare aid uuid;cid uuid;wid text;keys text[];r public.pro_work_file_mention_actions;answer jsonb;c public.pro_work_file_comments;
 m jsonb;uid uuid;gid uuid;source uuid;target public.pro_team_grants;nm text;seen uuid[]:=array[]::uuid[];names text[]:=array[]::text[];
 service text;file_name text;vno integer;excerpt text;result jsonb;
begin
 if not coalesce(public.pro_private_work_tools_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;
 keys:=public.pro_wfv_keys(p_input);
 if jsonb_typeof(p_input) is distinct from 'object' or keys is distinct from array['action','actionId','body','commentId','fileId','mentions','thread','versionNo','workId']
  or p_input->>'action' is distinct from 'comment_create' or jsonb_typeof(p_input->'thread') is distinct from 'string' or p_input->>'thread' is distinct from 'team' then raise exception 'Invalid mention comment fields' using errcode='22023';end if;
 if jsonb_typeof(p_input->'mentions') is distinct from 'array' or jsonb_array_length(p_input->'mentions') not between 1 and 10 then raise exception 'Invalid mentions' using errcode='22023';end if;
 aid:=public.pro_wfv_uuid(p_input->'actionId');cid:=public.pro_wfv_uuid(p_input->'commentId');
 if jsonb_typeof(p_input->'workId') is distinct from 'string' or length(p_input->>'workId') not between 1 and 160 then raise exception 'Invalid job' using errcode='22023';end if;
 wid:=p_input->>'workId';
 if not exists(select 1 from public.pro_work where user_id=p_actor and id=wid) then raise exception 'Forbidden' using errcode='42501';end if;
 perform pg_advisory_xact_lock(hashtextextended('pro-wfm-action:'||p_actor::text||':'||aid::text,0));
 select * into r from public.pro_work_file_mention_actions where actor_id=p_actor and action_id=aid;
 if found then
  if r.input is distinct from p_input then raise exception 'Action identity reused with different payload' using errcode='22023';end if;
  return r.result;
 end if;
 -- The same actionId already created a comment WITHOUT mentions: never attach mentions afterwards.
 if exists(select 1 from public.pro_work_file_version_actions where actor_id=p_actor and action_id=aid) then raise exception 'Comment identity reused' using errcode='22023';end if;
 answer:=public.pro_work_file_versions_mutate(p_actor,p_input-'mentions');
 select * into c from public.pro_work_file_comments where owner_id=p_actor and id=cid;
 if not found or c.thread<>'team' or c.author_kind<>'owner' or c.author_id<>p_actor or c.work_id<>wid then raise exception 'Comment unavailable' using errcode='42501';end if;
 for m in select value from jsonb_array_elements(p_input->'mentions') loop
  if public.pro_wfv_keys(m) is distinct from array['grantId','sourceInviteId','userId'] then raise exception 'Invalid mention target' using errcode='22023';end if;
  uid:=public.pro_wfv_uuid(m->'userId');gid:=public.pro_wfv_uuid(m->'grantId');source:=public.pro_wfv_uuid(m->'sourceInviteId');
  if uid=p_actor or uid=any(seen) then raise exception 'Invalid mention identity' using errcode='22023';end if;seen:=array_append(seen,uid);
  select * into target from public.pro_team_grants where id=gid for update;
  if not found or target.owner_id<>p_actor or target.work_id<>wid or target.member_user_id<>uid or not target.active or target.source_invite_id<>source
   or not exists(select 1 from public.profiles where id=uid and not coalesce(is_disabled,false)) then raise exception 'Mention target changed' using errcode='40001';end if;
  nm:=public.pro_wfm_member_name(target);
  if nm='' then raise exception 'Mention target changed' using errcode='40001';end if;
  if position(lower('@'||nm) in lower(c.body))=0 then raise exception 'Mention is not in the comment' using errcode='22023';end if;
  names:=array_append(names,nm);
  insert into public.pro_work_file_comment_mentions(owner_id,work_id,comment_id,recipient_id,name,recipient_grant_id,recipient_source_invite_id) values(p_actor,wid,cid,uid,nm,gid,source);
 end loop;
 -- Snapshot for the member: job service, file name of the commented (or current) version, excerpt.
 select left(coalesce(w.service,''),160) into service from public.pro_work w where w.user_id=p_actor and w.id=wid;
 vno:=c.version_no;
 select f.name into file_name from public.pro_work_file_families fam join public.pro_work_file_versions v on v.owner_id=fam.owner_id and v.family_id=fam.id and v.version_no=coalesce(vno,fam.current_version)
  join public.pro_work_files f on f.owner_id=v.owner_id and f.id=v.file_id where fam.owner_id=p_actor and fam.id=c.family_id;
 if file_name is null then select f.name into file_name from public.pro_work_files f where f.owner_id=p_actor and f.id=c.family_id;end if;
 excerpt:=case when length(c.body)>280 then left(c.body,279)||'…' else c.body end;
 insert into public.pro_work_file_mention_notices(recipient_id,owner_id,work_id,comment_id,actor_id,actor_name,recipient_grant_id,recipient_source_invite_id,service,file_name,version_no,excerpt)
  select mm.recipient_id,p_actor,wid,cid,p_actor,c.author_name,mm.recipient_grant_id,mm.recipient_source_invite_id,coalesce(service,''),file_name,vno,excerpt
  from public.pro_work_file_comment_mentions mm where mm.comment_id=cid;
 result:=jsonb_build_object('comment',answer->'comment','mentions',public.pro_wfm_mentions_json(cid));
 insert into public.pro_work_file_mention_actions(actor_id,action_id,owner_id,comment_id,input,result) values(p_actor,aid,p_actor,cid,p_input,result);
 return result;
end $$;

-- ===================================================================== owner reads
-- Recorded mentions of up to 20 comments of this owner/job (for chips in the team thread).
create or replace function public.pro_work_file_comment_mentions_read(p_actor uuid,p_work text,p_comments uuid[]) returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
begin
 if not coalesce(public.pro_private_work_tools_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;
 if p_work is null or not exists(select 1 from public.pro_work where user_id=p_actor and id=p_work) then raise exception 'Forbidden' using errcode='42501';end if;
 if p_comments is null or cardinality(p_comments) not between 1 and 20 or array_position(p_comments,null) is not null then raise exception 'Invalid comment list' using errcode='22023';end if;
 return jsonb_build_object('workId',p_work,'items',coalesce((select jsonb_agg(jsonb_build_object('commentId',c.id,'mentions',public.pro_wfm_mentions_json(c.id)) order by c.id)
  from public.pro_work_file_comments c where c.owner_id=p_actor and c.work_id=p_work and c.thread='team' and c.id=any(p_comments)
  and exists(select 1 from public.pro_work_file_comment_mentions m where m.comment_id=c.id)),'[]'::jsonb));
end $$;

-- ===================================================================== member inbox
create or replace function public.pro_work_file_mention_notice_allowed(p_actor uuid,p_notice public.pro_work_file_mention_notices) returns boolean
language sql stable security invoker set search_path=public,pg_temp as $$
 select p_notice.recipient_id=p_actor and exists(select 1 from public.profiles p where p.id=p_actor and not coalesce(p.is_disabled,false))
 and coalesce(public.pro_private_work_tools_enabled(p_notice.owner_id),false)
 and exists(select 1 from public.pro_work_file_comments c where c.owner_id=p_notice.owner_id and c.id=p_notice.comment_id and c.thread='team' and c.archived_at is null)
 and exists(select 1 from public.pro_team_grants g where g.id=p_notice.recipient_grant_id and g.owner_id=p_notice.owner_id and g.work_id=p_notice.work_id
  and g.member_user_id=p_actor and g.active and g.source_invite_id=p_notice.recipient_source_invite_id);
$$;
-- Never returns owner/job/file identifiers: the member has no file access.
create or replace function public.pro_work_file_mention_notice_json(p_notice public.pro_work_file_mention_notices) returns jsonb
language sql stable security invoker set search_path=public,pg_temp as $$
 select jsonb_build_object('id',p_notice.id,'service',p_notice.service,'fileName',p_notice.file_name,'versionNo',p_notice.version_no,'authorName',p_notice.actor_name,
  'excerpt',p_notice.excerpt,'createdAt',p_notice.created_at,'dayCr',public.pro_wfv_day(p_notice.created_at),'readAt',p_notice.read_at);
$$;
create or replace function public.pro_work_file_mention_inbox(p_actor uuid,p_status text default 'unread',p_after uuid default null) returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare items jsonb;cursor_id uuid;cursor_at timestamptz;unread_count bigint;
begin
 if not exists(select 1 from public.profiles where id=p_actor and not coalesce(is_disabled,false)) then raise exception 'Forbidden' using errcode='42501';end if;
 if p_status is null or p_status not in('all','unread') then raise exception 'Invalid inbox status' using errcode='22023';end if;
 if p_after is not null then
  select created_at into cursor_at from public.pro_work_file_mention_notices n where n.id=p_after and public.pro_work_file_mention_notice_allowed(p_actor,n) and(p_status='all' or n.read_at is null);
  if not found then raise exception 'Invalid notice cursor' using errcode='22023';end if;
 end if;
 select count(*) into unread_count from public.pro_work_file_mention_notices n where n.recipient_id=p_actor and n.read_at is null and public.pro_work_file_mention_notice_allowed(p_actor,n);
 select coalesce(jsonb_agg(public.pro_work_file_mention_notice_json(n::public.pro_work_file_mention_notices) order by n.created_at desc,n.id desc),'[]'::jsonb) into items from(
  select * from public.pro_work_file_mention_notices n where n.recipient_id=p_actor and public.pro_work_file_mention_notice_allowed(p_actor,n) and(p_status='all' or n.read_at is null)
  and(p_after is null or(n.created_at,n.id)<(cursor_at,p_after)) order by n.created_at desc,n.id desc limit 21) n;
 if jsonb_array_length(items)>20 then cursor_id:=(items->19->>'id')::uuid;items:=items-20;end if;
 return jsonb_build_object('items',items,'nextCursor',cursor_id,'unreadCount',unread_count);
end $$;
create or replace function public.pro_work_file_mention_notice_mark_read(p_actor uuid,p_input jsonb) returns jsonb
language plpgsql security invoker set search_path=public,pg_temp as $$
declare n public.pro_work_file_mention_notices;r public.pro_work_file_mention_notice_actions;aid uuid;nid uuid;answer jsonb;
begin
 if jsonb_typeof(p_input) is distinct from 'object' or public.pro_wfv_keys(p_input) is distinct from array['action','actionId','noticeId'] or p_input->>'action' is distinct from 'mark_read' then raise exception 'Invalid notice action' using errcode='22023';end if;
 aid:=public.pro_wfv_uuid(p_input->'actionId');nid:=public.pro_wfv_uuid(p_input->'noticeId');
 perform pg_advisory_xact_lock(hashtextextended('pro-wfm-notice:'||p_actor::text||':'||aid::text,0));
 select * into r from public.pro_work_file_mention_notice_actions where actor_id=p_actor and action_id=aid;
 if found then
  if r.input is distinct from p_input then raise exception 'Notice action reused' using errcode='22023';end if;
  select * into n from public.pro_work_file_mention_notices where id=r.notice_id;
  if not found or not public.pro_work_file_mention_notice_allowed(p_actor,n) then raise exception 'Notice unavailable' using errcode='42501';end if;
  return r.result;
 end if;
 select * into n from public.pro_work_file_mention_notices where id=nid;
 if not found then raise exception 'Notice unavailable' using errcode='42501';end if;
 perform 1 from public.pro_team_grants where id=n.recipient_grant_id for share;
 select * into n from public.pro_work_file_mention_notices where id=nid for update;
 if not public.pro_work_file_mention_notice_allowed(p_actor,n) then raise exception 'Notice unavailable' using errcode='42501';end if;
 if n.read_at is null then update public.pro_work_file_mention_notices set read_at=clock_timestamp() where id=nid returning * into n;end if;
 answer:=jsonb_build_object('noticeId',n.id,'readAt',n.read_at);
 insert into public.pro_work_file_mention_notice_actions(actor_id,action_id,notice_id,input,result) values(p_actor,aid,nid,p_input,answer);
 return answer;
end $$;

-- ===================================================================== immutability
create or replace function public.pro_wfm_immutable() returns trigger
language plpgsql security invoker set search_path=public,pg_temp as $$
begin raise exception 'File mentions and receipts are immutable' using errcode='23514';end $$;
create or replace function public.pro_wfm_notice_guard() returns trigger
language plpgsql security invoker set search_path=public,pg_temp as $$
begin
 if (to_jsonb(new)-'read_at') is distinct from (to_jsonb(old)-'read_at') or old.read_at is not null or new.read_at is null then raise exception 'Notice content is immutable' using errcode='23514';end if;
 return new;
end $$;
drop trigger if exists pro_wfm_mentions_immutable on public.pro_work_file_comment_mentions;
create trigger pro_wfm_mentions_immutable before update on public.pro_work_file_comment_mentions for each row execute function public.pro_wfm_immutable();
drop trigger if exists pro_wfm_actions_immutable on public.pro_work_file_mention_actions;
create trigger pro_wfm_actions_immutable before update on public.pro_work_file_mention_actions for each row execute function public.pro_wfm_immutable();
drop trigger if exists pro_wfm_notice_actions_immutable on public.pro_work_file_mention_notice_actions;
create trigger pro_wfm_notice_actions_immutable before update on public.pro_work_file_mention_notice_actions for each row execute function public.pro_wfm_immutable();
drop trigger if exists pro_wfm_notice_guard on public.pro_work_file_mention_notices;
create trigger pro_wfm_notice_guard before update on public.pro_work_file_mention_notices for each row execute function public.pro_wfm_notice_guard();

alter table public.pro_work_file_comment_mentions enable row level security;
alter table public.pro_work_file_mention_actions enable row level security;
alter table public.pro_work_file_mention_notices enable row level security;
alter table public.pro_work_file_mention_notice_actions enable row level security;
revoke all on public.pro_work_file_comment_mentions,public.pro_work_file_mention_actions,public.pro_work_file_mention_notices,public.pro_work_file_mention_notice_actions from public,anon,authenticated;
grant select,insert,update,delete on public.pro_work_file_comment_mentions,public.pro_work_file_mention_actions,public.pro_work_file_mention_notices,public.pro_work_file_mention_notice_actions to service_role;
revoke all on function public.pro_wfm_member_name(public.pro_team_grants),public.pro_work_file_mention_targets(uuid,text),public.pro_wfm_mentions_json(uuid),
 public.pro_work_file_comment_with_mentions(uuid,jsonb),public.pro_work_file_comment_mentions_read(uuid,text,uuid[]),
 public.pro_work_file_mention_notice_allowed(uuid,public.pro_work_file_mention_notices),public.pro_work_file_mention_notice_json(public.pro_work_file_mention_notices),
 public.pro_work_file_mention_inbox(uuid,text,uuid),public.pro_work_file_mention_notice_mark_read(uuid,jsonb),public.pro_wfm_immutable(),public.pro_wfm_notice_guard() from public,anon,authenticated;
grant execute on function public.pro_wfm_member_name(public.pro_team_grants),public.pro_work_file_mention_targets(uuid,text),public.pro_wfm_mentions_json(uuid),
 public.pro_work_file_comment_with_mentions(uuid,jsonb),public.pro_work_file_comment_mentions_read(uuid,text,uuid[]),
 public.pro_work_file_mention_notice_allowed(uuid,public.pro_work_file_mention_notices),public.pro_work_file_mention_notice_json(public.pro_work_file_mention_notices),
 public.pro_work_file_mention_inbox(uuid,text,uuid),public.pro_work_file_mention_notice_mark_read(uuid,jsonb) to service_role;
commit;
notify pgrst,'reload schema';

-- ===== file-formats-library-local.sql =====
-- LOCAL PRO ONLY. Ronda F2-D (2026-11-19): formats, organizer, library tags and shared folders.
-- Rows 28, 29, 31 and 33 of docs/pro/houzz-parity-register-local.md.
-- 1. Formats (row 28): job files (pro_work_files) and the company library (pro_company_files)
--    accept, besides JPG/PDF: Word/Excel/PowerPoint (OOXML, no macros), CSV, TXT, AutoCAD DWG/DXF
--    (download only), HEIC (kept when it cannot be converted to JPG) and short MP4/MOV videos, all
--    up to the same 20 MiB private limit (file-size-limits-local.sql). The server sniffs the bytes
--    (src/lib/pro/file-sniff.ts); the list below is the same as src/lib/pro/file-formats.ts. Every
--    bucket stays private (no public URL, no signed URL handed out): bytes only through the
--    reauthorized API. The CHECK constraints that hard-coded jpg/pdf are replaced by format-aware
--    ones (no row changes: every stored jpg/pdf already satisfies them).
-- 2. Quota (row 28): 2 GiB per account across job files and library (new uploads only), 500 files
--    per job (was 100) and 1000 library files (was 500).
-- 3. Organizer (row 29): permanent delete from the trash with confirmation (purge_file /
--    purge_folder). Only files never shared with the customer and without versions, comments or
--    other uses (any foreign key besides the organizer metadata) can be deleted; the route then
--    removes the stored bytes. The organizer history keeps the record. Nothing is purged
--    automatically after the 30 days.
-- 4. Shared folders (row 33): share_folder marks a job folder "Visible para el cliente"; the linked
--    customer (and the owner's "as client" preview) sees the ready, non-trashed files directly in
--    it, only while "Archivos y fotos" (show_files) is on. Downloads are reauthorized each time.
-- 5. Library tags (row 31): up to 6 tags per library file (presets template/manual/permit plus
--    custom), list and filter by tag. Private to the owner, like the library.
-- Patterns: RLS on, service_role-only, security invoker, idempotent actionId receipts, CAS 40001.
begin;
create or replace function public.pro_file_doc_ext(p_mime text) returns text language sql immutable security invoker set search_path=public,pg_temp as $$
 select case p_mime when 'image/jpeg' then 'jpg' when 'application/pdf' then 'pdf'
  when 'application/vnd.openxmlformats-officedocument.wordprocessingml.document' then 'docx'
  when 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' then 'xlsx'
  when 'application/vnd.openxmlformats-officedocument.presentationml.presentation' then 'pptx'
  when 'text/csv' then 'csv' when 'text/plain' then 'txt' when 'image/vnd.dwg' then 'dwg' when 'image/vnd.dxf' then 'dxf'
  when 'image/heic' then 'heic' when 'video/mp4' then 'mp4' when 'video/quicktime' then 'mov' end $$;

-- ===================================================================== 1. table checks
do $$declare r record;t regclass;begin
 foreach t in array array['public.pro_work_files','public.pro_company_files']::regclass[] loop
  for r in select c.conname from pg_constraint c where c.conrelid=t and c.contype='c' and (pg_get_constraintdef(c.oid) like '%application/pdf%' or c.conname like 'pro\_%\_doc\_%') loop
   execute format('alter table %s drop constraint %I',t,r.conname);
  end loop;
 end loop;
 alter table public.pro_work_files add constraint pro_work_files_doc_mime check(mime_type in('image/jpeg','application/pdf','application/vnd.openxmlformats-officedocument.wordprocessingml.document','application/vnd.openxmlformats-officedocument.spreadsheetml.sheet','application/vnd.openxmlformats-officedocument.presentationml.presentation','text/csv','text/plain','image/vnd.dwg','image/vnd.dxf','image/heic','video/mp4','video/quicktime'));
 alter table public.pro_work_files add constraint pro_work_files_doc_path check(object_path=owner_id::text||'/'||id::text||'.'||public.pro_file_doc_ext(mime_type));
 alter table public.pro_work_files add constraint pro_work_files_doc_name check(right(name,length(public.pro_file_doc_ext(mime_type))+1)='.'||public.pro_file_doc_ext(mime_type));
 alter table public.pro_company_files add constraint pro_company_files_doc_mime check(mime_type in('image/jpeg','application/pdf','application/vnd.openxmlformats-officedocument.wordprocessingml.document','application/vnd.openxmlformats-officedocument.spreadsheetml.sheet','application/vnd.openxmlformats-officedocument.presentationml.presentation','text/csv','text/plain','image/vnd.dwg','image/vnd.dxf','image/heic','video/mp4','video/quicktime'));
 alter table public.pro_company_files add constraint pro_company_files_doc_path check(object_path=owner_id::text||'/'||id::text||'.'||public.pro_file_doc_ext(mime_type));
 alter table public.pro_company_files add constraint pro_company_files_doc_name check(right(name,length(public.pro_file_doc_ext(mime_type))+1)='.'||public.pro_file_doc_ext(mime_type));
end $$;

-- ===================================================================== 2. quota
create or replace function public.pro_file_quota_used(p_owner uuid) returns bigint language sql stable security invoker set search_path=public,pg_temp as $$
 select coalesce((select sum(size_bytes)::bigint from public.pro_work_files where owner_id=p_owner),0)+coalesce((select sum(size_bytes)::bigint from public.pro_company_files where owner_id=p_owner),0) $$;
create or replace function public.pro_file_quota_check(p_owner uuid,p_bytes integer) returns void language plpgsql stable security invoker set search_path=public,pg_temp as $$
begin
 if public.pro_file_quota_used(p_owner)+coalesce(p_bytes,0)>2147483648 then raise exception 'Storage quota exceeded' using errcode='54000',hint='pro_file_quota';end if;
end $$;
create or replace function public.pro_file_quota_read(p_actor uuid) returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$
begin
 if not coalesce(public.pro_appointment_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;
 return jsonb_build_object('usedBytes',public.pro_file_quota_used(p_actor),'limitBytes',2147483648);
end $$;

-- ===================================================================== writers (same bodies, format-aware)
create or replace function public.pro_work_file_reserve(p_actor uuid,p_input jsonb) returns jsonb
language plpgsql security invoker set search_path=public,pg_temp as $$
declare fid uuid;wid text;keys text[];receipt public.pro_work_file_upload_actions;file public.pro_work_files;mime text;bytes integer;path text;
begin
 if not coalesce(public.pro_appointment_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;
 if jsonb_typeof(p_input) is distinct from 'object' then raise exception 'Invalid file' using errcode='22023';end if;
 select array_agg(key order by key) into keys from jsonb_object_keys(p_input) key;
 if keys<>array['fileId','mimeType','name','rawSha256','sha256','sizeBytes','sourceName','workId']
 or jsonb_typeof(p_input->'fileId') is distinct from 'string' or jsonb_typeof(p_input->'workId') is distinct from 'string'
 or jsonb_typeof(p_input->'name') is distinct from 'string' or jsonb_typeof(p_input->'sourceName') is distinct from 'string'
 or jsonb_typeof(p_input->'mimeType') is distinct from 'string' or jsonb_typeof(p_input->'rawSha256') is distinct from 'string' or jsonb_typeof(p_input->'sha256') is distinct from 'string'
 or jsonb_typeof(p_input->'sizeBytes') is distinct from 'number' then raise exception 'Invalid file fields' using errcode='22023';end if;
 fid:=(p_input->>'fileId')::uuid;wid:=p_input->>'workId';mime:=p_input->>'mimeType';
 if length(wid) not between 1 and 160 or public.pro_file_doc_ext(mime) is null or not coalesce((p_input->>'rawSha256')~'^[a-f0-9]{64}$',false) or not coalesce((p_input->>'sha256')~'^[a-f0-9]{64}$',false)
 or not coalesce((p_input->>'sizeBytes')~'^[0-9]{1,8}$',false) then raise exception 'Invalid file metadata' using errcode='22023';end if;
 bytes:=(p_input->>'sizeBytes')::integer;if bytes<1 or bytes>20971520 or mime='image/jpeg' and bytes>20971520 or right(p_input->>'name',length(public.pro_file_doc_ext(mime))+1)<>'.'||public.pro_file_doc_ext(mime) then raise exception 'File too large' using errcode='22023';end if;
 if not exists(select 1 from public.pro_work where user_id=p_actor and id=wid) then raise exception 'Forbidden' using errcode='42501';end if;
 perform pg_advisory_xact_lock(hashtextextended('pro-work-file-upload:'||p_actor::text||':'||fid::text,0));
 select * into receipt from public.pro_work_file_upload_actions where actor_id=p_actor and file_id=fid;
 if found then
  if receipt.input is distinct from p_input then raise exception 'Upload identity reused with different bytes or metadata' using errcode='22023';end if;
  select * into file from public.pro_work_files where id=fid and owner_id=p_actor and work_id=wid;
  return jsonb_build_object('file',coalesce(receipt.result->'file',public.pro_work_file_json(file)),'objectPath',file.object_path);
 end if;
 perform pg_advisory_xact_lock(hashtextextended('pro-work-files:'||p_actor::text||':'||wid,0));
 perform 1 from public.pro_work where user_id=p_actor and id=wid for update;
 if not found then raise exception 'Forbidden' using errcode='42501';end if;
 if (select count(*) from public.pro_work_files where owner_id=p_actor and work_id=wid)>=500 then raise exception 'File limit reached' using errcode='54000';end if;
 perform public.pro_file_quota_check(p_actor,bytes);
 path:=p_actor::text||'/'||fid::text||'.'||public.pro_file_doc_ext(mime);
 insert into public.pro_work_files(id,owner_id,work_id,source_name,name,mime_type,raw_sha256,sha256,size_bytes,object_path)
 values(fid,p_actor,wid,p_input->>'sourceName',p_input->>'name',mime,p_input->>'rawSha256',p_input->>'sha256',bytes,path) returning * into file;
 insert into public.pro_work_file_upload_actions(actor_id,file_id,input) values(p_actor,fid,p_input);
 return jsonb_build_object('file',public.pro_work_file_json(file),'objectPath',path);
end $$;

create or replace function public.pro_company_files_mutate(p_actor uuid,p_input jsonb,p_input_hash text) returns jsonb language plpgsql security invoker set search_path=public,pg_temp as $$
declare act text;aid uuid;fid uuid;parent uuid;rev integer;keys text[];expected text[];r pro_company_file_actions;f pro_company_files;folder pro_company_folders;before_json jsonb;answer jsonb;ancestors jsonb;max_depth integer;target uuid;wid text;snapshot jsonb;reserved jsonb;bytes integer;mime text;canonical_name text;
begin
 if not coalesce(pro_appointment_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;
 if jsonb_typeof(p_input) is distinct from 'object' or not coalesce(p_input_hash~'^[a-f0-9]{64}$',false) or jsonb_typeof(p_input->'actionId') is distinct from 'string' then raise exception 'Invalid operation' using errcode='22023';end if;
 act:=p_input->>'action';aid:=(p_input->>'actionId')::uuid;
 case act
 when 'folder_save' then expected:=array['action','actionId','favorite','folderId','name','parentId','revision'];
 when 'folder_archive','folder_restore' then expected:=array['action','actionId','folderId','revision'];
 when 'file_update' then expected:=array['action','actionId','favorite','fileId','folderId','name','revision'];
 when 'file_archive','file_restore' then expected:=array['action','actionId','fileId','revision'];
 when 'upload' then expected:=array['action','actionId','fileId','folderId','mimeType','name','rawSha256','sha256','sizeBytes','sourceName'];
 when 'copy' then expected:=array['action','actionId','fileId','revision','targetFileId','workId'];
 else raise exception 'Invalid action' using errcode='22023';end case;
 select array_agg(key order by key) into keys from jsonb_object_keys(p_input)key;if keys is distinct from expected then raise exception 'Invalid action fields' using errcode='22023';end if;
 if act<>'upload' and(jsonb_typeof(p_input->'revision') is distinct from 'number' or not coalesce((p_input->>'revision')~'^[0-9]{1,10}$',false) or(p_input->>'revision')::numeric not between 0 and 2147483647) then raise exception 'Invalid revision' using errcode='22023';end if;
 if act<>'upload' then rev:=(p_input->>'revision')::integer;end if;
 perform pg_advisory_xact_lock(hashtextextended('pro-company-file-action:'||p_actor::text||':'||aid::text,0));
 if not coalesce(pro_appointment_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;
 select * into r from pro_company_file_actions where actor_id=p_actor and action_id=aid;
 if found then if r.input is distinct from p_input or r.input_hash<>p_input_hash then raise exception 'Operation identity reused' using errcode='22023';end if;return pro_company_action_state(p_actor,aid);end if;
 if act='copy' then if jsonb_typeof(p_input->'targetFileId') is distinct from 'string' or jsonb_typeof(p_input->'fileId') is distinct from 'string' then raise exception 'Invalid copy identity' using errcode='22023';end if;target:=(p_input->>'targetFileId')::uuid;perform pg_advisory_xact_lock(hashtextextended('pro-work-file-upload:'||p_actor::text||':'||target::text,0));end if;
 perform pg_advisory_xact_lock(hashtextextended('pro-company-files:'||p_actor::text,0));
 if not coalesce(pro_appointment_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;
 if act like 'folder_%' then
  if jsonb_typeof(p_input->'folderId') is distinct from 'string' then raise exception 'Invalid folder identity' using errcode='22023';end if;fid:=(p_input->>'folderId')::uuid;
  select * into folder from pro_company_folders where owner_id=p_actor and id=fid for update;
  if found then if rev<>folder.revision or rev=0 then raise exception 'Folder changed' using errcode='40001';end if;before_json:=pro_company_folder_json(folder);
  elsif act<>'folder_save' or rev<>0 then raise exception 'Folder missing' using errcode='42501';end if;
  if rev>=2147483647 then raise exception 'Revision exhausted' using errcode='40001';end if;
  if act='folder_save' then
   if folder.archived or jsonb_typeof(p_input->'name') is distinct from 'string' or length(btrim(p_input->>'name')) not between 1 and 80 or(p_input->>'name')~'[[:cntrl:]/\\]' or jsonb_typeof(p_input->'favorite') is distinct from 'boolean' or jsonb_typeof(p_input->'parentId') is null or jsonb_typeof(p_input->'parentId') not in('string','null') then raise exception 'Invalid folder' using errcode='22023';end if;
   parent:=(p_input->>'parentId')::uuid;ancestors:=pro_company_ancestors(p_actor,parent);
   if fid=parent or exists(select 1 from jsonb_array_elements(ancestors)x where x->>'id'=fid::text) then raise exception 'Folder cycle' using errcode='40001';end if;
   with recursive subtree(id,depth) as(select fid,1 union all select d.id,s.depth+1 from pro_company_folders d join subtree s on d.parent_id=s.id where d.owner_id=p_actor)select max(depth) into max_depth from subtree;
   if jsonb_array_length(ancestors)+max_depth>5 then raise exception 'Folder depth exceeds five' using errcode='40001';end if;
   if rev=0 and(select count(*) from pro_company_folders where owner_id=p_actor)>=100 then raise exception 'Folder capacity exceeded' using errcode='40001';end if;
   insert into pro_company_folders(owner_id,id,parent_id,name,revision,favorite) values(p_actor,fid,parent,btrim(p_input->>'name'),rev+1,(p_input->>'favorite')::boolean) on conflict(owner_id,id) do update set parent_id=excluded.parent_id,name=excluded.name,revision=excluded.revision,favorite=excluded.favorite returning * into folder;
  else
   if folder.archived=(act='folder_archive') then raise exception 'Folder status changed' using errcode='40001';end if;
   if act='folder_archive' and(exists(select 1 from pro_company_folders where owner_id=p_actor and parent_id=fid) or exists(select 1 from pro_company_files where owner_id=p_actor and folder_id=fid)) then raise exception 'Move the folder contents before archiving' using errcode='40001';end if;
   perform pro_company_ancestors(p_actor,folder.parent_id);update pro_company_folders set archived=(act='folder_archive'),revision=revision+1 where owner_id=p_actor and id=fid returning * into folder;
  end if;answer:=jsonb_build_object('action',act,'folder',pro_company_folder_json(folder));
 elsif act='upload' then
  if jsonb_typeof(p_input->'fileId') is distinct from 'string' or jsonb_typeof(p_input->'folderId') is null or jsonb_typeof(p_input->'folderId') not in('null','string') or jsonb_typeof(p_input->'sourceName') is distinct from 'string' or length(p_input->>'sourceName') not between 1 and 160 or jsonb_typeof(p_input->'name') is distinct from 'string' or jsonb_typeof(p_input->'sizeBytes') is distinct from 'number' or not coalesce((p_input->>'sizeBytes')~'^[0-9]{1,8}$',false) or not coalesce((p_input->>'sha256')~'^[a-f0-9]{64}$',false) or not coalesce((p_input->>'rawSha256')~'^[a-f0-9]{64}$',false) or jsonb_typeof(p_input->'mimeType') is distinct from 'string' or public.pro_file_doc_ext(p_input->>'mimeType') is null then raise exception 'Invalid file reservation' using errcode='22023';end if;
  fid:=(p_input->>'fileId')::uuid;parent:=(p_input->>'folderId')::uuid;perform pro_company_ancestors(p_actor,parent);
  if exists(select 1 from pro_company_files where owner_id=p_actor and id=fid) then raise exception 'File identity already used' using errcode='40001';end if;
  if(select count(*) from pro_company_files where owner_id=p_actor)>=1000 then raise exception 'File capacity exceeded' using errcode='40001';end if;
  perform public.pro_file_quota_check(p_actor,(p_input->>'sizeBytes')::integer);
  mime:=p_input->>'mimeType';bytes:=(p_input->>'sizeBytes')::integer;canonical_name:=p_input->>'name';
  if bytes not between 1 and 20971520 or mime='image/jpeg' and bytes>20971520 or length(canonical_name) not between 1 and 160 or canonical_name~'[[:cntrl:]/\\]' or right(canonical_name,length(public.pro_file_doc_ext(mime))+1)<>'.'||public.pro_file_doc_ext(mime) then raise exception 'Invalid canonical file' using errcode='22023';end if;
  insert into pro_company_files(owner_id,id,folder_id,name,mime_type,size_bytes,sha256,object_path) values(p_actor,fid,parent,canonical_name,mime,bytes,p_input->>'sha256',p_actor::text||'/'||fid::text||'.'||public.pro_file_doc_ext(mime)) returning * into f;
 elsif act='copy' then
  fid:=(p_input->>'fileId')::uuid;wid:=p_input->>'workId';if jsonb_typeof(p_input->'workId') is distinct from 'string' or length(wid) not between 1 and 160 then raise exception 'Invalid work' using errcode='22023';end if;
  select * into f from pro_company_files where owner_id=p_actor and id=fid and ready and not archived for share;if not found then raise exception 'Source unavailable' using errcode='42501';end if;if f.revision<>rev then raise exception 'Source changed' using errcode='40001';end if;perform pro_company_ancestors(p_actor,f.folder_id);
  perform pg_advisory_xact_lock(hashtextextended('pro-work-files:'||p_actor::text||':'||wid,0));
  perform 1 from pro_work where user_id=p_actor and id=wid for update;if not found then raise exception 'Forbidden' using errcode='42501';end if;
  if exists(select 1 from pro_work where user_id=p_actor and id=wid and coalesce(cancelled,false)) then raise exception 'Work cancelled' using errcode='40001';end if;
  if exists(select 1 from pro_work_files where id=target) or exists(select 1 from pro_work_file_upload_actions where actor_id=p_actor and file_id=target) then raise exception 'Target identity used' using errcode='40001';end if;
  if(select count(*) from pro_work_files where owner_id=p_actor and work_id=wid)>=500 then raise exception 'Work files capacity exceeded' using errcode='40001';end if;
  snapshot:=pro_company_file_json(f);reserved:=pro_work_file_reserve(p_actor,jsonb_build_object('fileId',target,'workId',wid,'sourceName',f.name,'name',f.name,'mimeType',f.mime_type,'rawSha256',f.sha256,'sha256',f.sha256,'sizeBytes',f.size_bytes));
 else
  fid:=(p_input->>'fileId')::uuid;select * into f from pro_company_files where owner_id=p_actor and id=fid and ready for update;if not found then raise exception 'File missing' using errcode='42501';end if;if rev<>f.revision then raise exception 'File changed' using errcode='40001';end if;if rev>=2147483647 then raise exception 'Revision exhausted' using errcode='40001';end if;before_json:=pro_company_file_json(f);
  if act='file_update' then
   if f.archived then raise exception 'File archived' using errcode='40001';end if;
   if jsonb_typeof(p_input->'folderId') is null or jsonb_typeof(p_input->'folderId') not in('null','string') or jsonb_typeof(p_input->'favorite') is distinct from 'boolean' or jsonb_typeof(p_input->'name') is distinct from 'string' then raise exception 'Invalid file metadata' using errcode='22023';end if;
   parent:=(p_input->>'folderId')::uuid;perform pro_company_ancestors(p_actor,parent);canonical_name:=p_input->>'name';if length(canonical_name) not between 1 and 160 or canonical_name~'[[:cntrl:]/\\]' or right(canonical_name,length(public.pro_file_doc_ext(f.mime_type))+1)<>'.'||public.pro_file_doc_ext(f.mime_type) then raise exception 'Invalid file name' using errcode='22023';end if;
   update pro_company_files set name=canonical_name,folder_id=parent,favorite=(p_input->>'favorite')::boolean,revision=revision+1 where owner_id=p_actor and id=fid returning * into f;
  else
   if f.archived=(act='file_archive') then raise exception 'File status changed' using errcode='40001';end if;perform pro_company_ancestors(p_actor,f.folder_id);update pro_company_files set archived=(act='file_archive'),revision=revision+1 where owner_id=p_actor and id=fid returning * into f;
  end if;answer:=jsonb_build_object('action',act,'file',pro_company_file_json(f));
 end if;
 if not coalesce(pro_appointment_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;
 insert into pro_company_file_actions(actor_id,action_id,input,input_hash,result,before_state,after_state) values(p_actor,aid,p_input,p_input_hash,answer,before_json,case when answer is null then null else answer end);
 if act='copy' then insert into pro_company_file_copies(owner_id,action_id,source_file_id,source_revision,source_snapshot,source_path,work_id,target_file_id) values(p_actor,aid,fid,f.revision,snapshot,f.object_path,wid,target);end if;
 return pro_company_action_state(p_actor,aid);
end $$;

-- ===================================================================== 3/4. organizer
alter table public.pro_work_file_folders add column if not exists client_visible boolean not null default false;
-- True when another record (version, comment, selection, takeoff, punch list, subcontractor access,
-- any future foreign key) uses the file. The organizer metadata and the upload receipt do not count.
create or replace function public.pro_wfo_file_in_use(p_file uuid) returns boolean language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare r record;hit boolean;col name;
begin
 for r in select c.conrelid::regclass rel,c.conkey,c.confkey,c.conrelid from pg_constraint c
  where c.contype='f' and c.confrelid='public.pro_work_files'::regclass and c.conrelid not in('public.pro_work_file_meta'::regclass,'public.pro_work_file_upload_actions'::regclass) loop
  select a.attname into col from unnest(r.conkey,r.confkey) k(own,ref) join pg_attribute fa on fa.attrelid='public.pro_work_files'::regclass and fa.attnum=k.ref and fa.attname='id' join pg_attribute a on a.attrelid=r.conrelid and a.attnum=k.own;
  if col is null then continue;end if;
  execute format('select exists(select 1 from %s where %I=$1)',r.rel,col) using p_file into hit;
  if hit then return true;end if;
 end loop;
 return false;
end $$;
create or replace function public.pro_wfo_folder_json(f public.pro_work_file_folders) returns jsonb language sql stable security invoker set search_path=public,pg_temp as $$
 select jsonb_build_object('id',f.id,'parentId',f.parent_id,'name',f.name,'revision',f.revision,'trashedAt',f.trashed_at,'clientVisible',f.client_visible,
  'restoreUntil',case when f.trashed_at is not null then ((f.trashed_at at time zone 'America/Costa_Rica')::date+30)::text end,
  'items',(select count(*) from public.pro_work_file_meta m where m.owner_id=f.owner_id and m.folder_id=f.id and m.trashed_at is null)+(select count(*) from public.pro_work_file_folders c where c.owner_id=f.owner_id and c.parent_id=f.id and c.trashed_at is null))
$$;

create or replace function public.pro_work_file_organizer_mutate(p_actor uuid,p_input jsonb) returns jsonb
language plpgsql security invoker set search_path=public,pg_temp as $$
declare act text:=p_input->>'action';aid uuid;wid text:=p_input->>'workId';keys text[];hash text:=md5(p_input::text);prior public.pro_work_file_organizer_actions;
 fo public.pro_work_file_folders;m public.pro_work_file_meta;w public.pro_work_files;target uuid;sid uuid;rev integer;nm text;before_json jsonb;after_json jsonb;answer jsonb;subj text;had_meta boolean;ext text;paths jsonb:='[]'::jsonb;sub uuid[];
begin
 if not coalesce(public.pro_private_work_tools_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;
 if jsonb_typeof(p_input) is distinct from 'object' then raise exception 'Invalid file action' using errcode='22023';end if;
 select array_agg(k order by k) into keys from jsonb_object_keys(p_input) k;
 if act is null or not(
   act='create_folder' and keys=array['action','actionId','folderId','name','parentId','workId']
   or act in('rename_folder','rename_file') and keys=array['action','actionId','name','revision','subjectId','workId']
   or act in('move_folder','move_file') and keys=array['action','actionId','revision','subjectId','targetId','workId']
   or act in('trash_folder','restore_folder','trash_file','restore_file') and keys=array['action','actionId','revision','subjectId','workId']
   or act='favorite_file' and keys=array['action','actionId','on','revision','subjectId','workId']
   or act in('purge_file','purge_folder') and keys=array['action','actionId','revision','subjectId','workId']
   or act='share_folder' and keys=array['action','actionId','on','revision','subjectId','workId']) then raise exception 'Invalid file action' using errcode='22023';end if;
 begin aid:=(p_input->>'actionId')::uuid;sid:=nullif(p_input->>'subjectId','')::uuid;target:=nullif(coalesce(p_input->>'targetId',p_input->>'parentId'),'')::uuid;
  if p_input ? 'revision' then rev:=(p_input->>'revision')::integer;end if;exception when others then raise exception 'Invalid file action' using errcode='22023';end;
 if wid is null or not exists(select 1 from public.pro_work where user_id=p_actor and id=wid) then raise exception 'Forbidden' using errcode='42501';end if;
 perform pg_advisory_xact_lock(hashtextextended('pro-wfo:'||p_actor::text||':'||wid,0));
 select * into prior from public.pro_work_file_organizer_actions where owner_id=p_actor and action_id=aid;
 if found then if prior.input_hash<>hash then raise exception 'Action id reused' using errcode='22023';end if;return prior.result||jsonb_build_object('replayed',true);end if;
 if target is not null and (not exists(select 1 from public.pro_work_file_folders where owner_id=p_actor and work_id=wid and id=target) or public.pro_wfo_folder_trashed(p_actor,target)) then raise exception 'Folder unavailable' using errcode='40001';end if;
 if act in('create_folder','rename_folder','rename_file') then
  if jsonb_typeof(p_input->'name') is distinct from 'string' then raise exception 'Invalid name' using errcode='22023';end if;nm:=btrim(p_input->>'name');
 end if;
 if act like '%_folder' then
  subj:='folder';
  if act='create_folder' then
   begin sid:=(p_input->>'folderId')::uuid;exception when others then raise exception 'Invalid file action' using errcode='22023';end;
   if length(nm) not between 1 and 80 or nm ~ '[[:cntrl:]/]' or position(chr(92) in nm)>0 then raise exception 'Invalid name' using errcode='22023';end if;
   if target is not null and public.pro_wfo_folder_depth(p_actor,target)>=5 then raise exception 'Folder too deep' using errcode='22023';end if;
   if (select count(*) from public.pro_work_file_folders where owner_id=p_actor and work_id=wid)>=200 then raise exception 'Folder limit' using errcode='54000';end if;
   insert into public.pro_work_file_folders(owner_id,id,work_id,parent_id,name) values(p_actor,sid,wid,target,nm) returning * into fo;
  else
   select * into fo from public.pro_work_file_folders where owner_id=p_actor and work_id=wid and id=sid for update;
   if not found then raise exception 'Forbidden' using errcode='42501';end if;
   if fo.revision<>rev then raise exception 'Folder changed' using errcode='40001';end if;
   before_json:=public.pro_wfo_folder_json(fo);
   if act='rename_folder' then
    if length(nm) not between 1 and 80 or nm ~ '[[:cntrl:]/]' or position(chr(92) in nm)>0 then raise exception 'Invalid name' using errcode='22023';end if;
    update public.pro_work_file_folders set name=nm,revision=revision+1 where owner_id=p_actor and id=sid returning * into fo;
   elsif act='move_folder' then
    if fo.trashed_at is not null then raise exception 'Restore before moving' using errcode='22023';end if;
    -- No cycles: the target cannot be the folder itself or one of its descendants.
    if target is not null and exists(with recursive down as(select id,1 h from public.pro_work_file_folders where owner_id=p_actor and id=sid union all select f.id,down.h+1 from public.pro_work_file_folders f join down on f.owner_id=p_actor and f.parent_id=down.id where down.h<8) select 1 from down where id=target) then raise exception 'Invalid move' using errcode='22023';end if;
    if coalesce(public.pro_wfo_folder_depth(p_actor,target),0)+public.pro_wfo_subtree_height(p_actor,sid)>5 then raise exception 'Folder too deep' using errcode='22023';end if;
    update public.pro_work_file_folders set parent_id=target,revision=revision+1 where owner_id=p_actor and id=sid returning * into fo;
   elsif act='trash_folder' then
    if fo.trashed_at is not null then raise exception 'Already in trash' using errcode='40001';end if;
    update public.pro_work_file_folders set trashed_at=clock_timestamp(),revision=revision+1 where owner_id=p_actor and id=sid returning * into fo;
   elsif act='share_folder' then
    -- Row 33: the linked customer sees the files directly inside a shared folder (show_files on).
    if fo.trashed_at is not null then raise exception 'Restore before sharing' using errcode='22023';end if;
    if jsonb_typeof(p_input->'on') is distinct from 'boolean' then raise exception 'Invalid file action' using errcode='22023';end if;
    update public.pro_work_file_folders set client_visible=(p_input->>'on')::boolean,revision=revision+1 where owner_id=p_actor and id=sid returning * into fo;
   elsif act='purge_folder' then
    -- Permanent delete from the trash: only when every file inside can be deleted (never shared, no versions/comments/uses).
    if fo.trashed_at is null then raise exception 'Not in trash' using errcode='40001';end if;
    with recursive down as(select id,1 h from public.pro_work_file_folders where owner_id=p_actor and id=sid union all select f.id,down.h+1 from public.pro_work_file_folders f join down on f.owner_id=p_actor and f.parent_id=down.id where down.h<8) select array_agg(id) into sub from down;
    if exists(select 1 from public.pro_work_file_meta mm join public.pro_work_files ww on ww.owner_id=mm.owner_id and ww.id=mm.file_id where mm.owner_id=p_actor and mm.folder_id=any(sub) and (ww.revision<>1 or public.pro_wfo_file_in_use(ww.id))) then raise exception 'File in use' using errcode='22023',hint='pro_file_in_use';end if;
    select coalesce(jsonb_agg(ww.object_path order by ww.id),'[]'::jsonb) into paths from public.pro_work_file_meta mm join public.pro_work_files ww on ww.owner_id=mm.owner_id and ww.id=mm.file_id where mm.owner_id=p_actor and mm.folder_id=any(sub);
    delete from public.pro_work_files ww using public.pro_work_file_meta mm where mm.owner_id=p_actor and mm.file_id=ww.id and ww.owner_id=p_actor and mm.folder_id=any(sub);
    delete from public.pro_work_file_folders d using (with recursive down as(select id,1 h from public.pro_work_file_folders where owner_id=p_actor and id=sid union all select f.id,down.h+1 from public.pro_work_file_folders f join down on f.owner_id=p_actor and f.parent_id=down.id where down.h<8) select id,h from down) x where d.owner_id=p_actor and d.id=x.id and x.h>1;
    delete from public.pro_work_file_folders where owner_id=p_actor and id=sid;
   else
    if fo.trashed_at is null then raise exception 'Not in trash' using errcode='40001';end if;
    -- Restored into the root when its parent is still in the trash.
    update public.pro_work_file_folders set trashed_at=null,parent_id=case when parent_id is not null and public.pro_wfo_folder_trashed(p_actor,parent_id) then null else parent_id end,revision=revision+1 where owner_id=p_actor and id=sid returning * into fo;
   end if;
  end if;
  after_json:=case when act='purge_folder' then jsonb_build_object('id',sid,'name',fo.name,'purged',true,'files',jsonb_array_length(paths)) else public.pro_wfo_folder_json(fo) end;answer:=jsonb_build_object('action',act,'folder',after_json,'objectPaths',paths);
 else
  subj:='file';
  select * into w from public.pro_work_files where owner_id=p_actor and work_id=wid and id=sid and ready;
  if not found then raise exception 'Forbidden' using errcode='42501';end if;
  select * into m from public.pro_work_file_meta where owner_id=p_actor and file_id=sid for update;
  had_meta:=found;
  if coalesce(m.revision,0)<>rev then raise exception 'File changed' using errcode='40001';end if;
  before_json:=public.pro_wfo_file_json(w,m);
  if not had_meta then insert into public.pro_work_file_meta(owner_id,file_id,work_id) values(p_actor,sid,wid) returning * into m;else update public.pro_work_file_meta set revision=revision+1,updated_at=clock_timestamp() where owner_id=p_actor and file_id=sid returning * into m;end if;
  if act='rename_file' then
   ext:='.'||public.pro_file_doc_ext(w.mime_type);
   if length(nm) not between length(ext)+1 and 160 or nm ~ '[[:cntrl:]/]' or position(chr(92) in nm)>0 or lower(right(nm,length(ext)))<>ext then raise exception 'Invalid name' using errcode='22023';end if;
   nm:=left(nm,length(nm)-length(ext))||ext;
   update public.pro_work_file_meta set display_name=case when nm=w.name then null else nm end where owner_id=p_actor and file_id=sid returning * into m;
  elsif act='move_file' then
   if m.trashed_at is not null then raise exception 'Restore before moving' using errcode='22023';end if;
   update public.pro_work_file_meta set folder_id=target where owner_id=p_actor and file_id=sid returning * into m;
  elsif act='favorite_file' then
   if jsonb_typeof(p_input->'on') is distinct from 'boolean' then raise exception 'Invalid file action' using errcode='22023';end if;
   update public.pro_work_file_meta set favorite=(p_input->>'on')::boolean where owner_id=p_actor and file_id=sid returning * into m;
  elsif act='trash_file' then
   if m.trashed_at is not null then raise exception 'Already in trash' using errcode='40001';end if;
   update public.pro_work_file_meta set trashed_at=clock_timestamp() where owner_id=p_actor and file_id=sid returning * into m;
  elsif act='purge_file' then
   if m.trashed_at is null then raise exception 'Not in trash' using errcode='40001';end if;
   if w.revision<>1 or public.pro_wfo_file_in_use(w.id) then raise exception 'File in use' using errcode='22023',hint='pro_file_in_use';end if;
   paths:=jsonb_build_array(w.object_path);
   delete from public.pro_work_files where owner_id=p_actor and id=sid;
  else
   if m.trashed_at is null then raise exception 'Not in trash' using errcode='40001';end if;
   update public.pro_work_file_meta set trashed_at=null,folder_id=case when folder_id is not null and public.pro_wfo_folder_trashed(p_actor,folder_id) then null else folder_id end where owner_id=p_actor and file_id=sid returning * into m;
  end if;
  after_json:=case when act='purge_file' then jsonb_build_object('id',sid,'name',coalesce(m.display_name,w.name),'purged',true) else public.pro_wfo_file_json(w,m) end;answer:=jsonb_build_object('action',act,'file',after_json,'objectPaths',paths);
 end if;
 insert into public.pro_work_file_organizer_history(owner_id,action_id,action,subject,subject_id,before_row,after_row) values(p_actor,aid,act,subj,sid,before_json,after_json);
 insert into public.pro_work_file_organizer_actions(owner_id,action_id,input_hash,result) values(p_actor,aid,hash,answer);
 return answer;
end $$;

-- Customer side of shared folders. Same link as pro_work_files_client_read (the appointment of
-- this customer account linked to the job) plus the "Archivos y fotos" switch.
create or replace function public.pro_work_file_folders_client_read(p_actor uuid,p_request uuid) returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare owner uuid;wid text;folders jsonb;
begin
 if not exists(select 1 from public.profiles where id=p_actor and not coalesce(is_disabled,false)) then raise exception 'Forbidden' using errcode='42501';end if;
 select owner_id,work_id into owner,wid from public.pro_appointment_requests where id=p_request and client_user_id=p_actor and work_id is not null;
 if not found then return null;end if;
 if not public.pro_wfv_client_files_visible(owner,wid) then return jsonb_build_object('folders','[]'::jsonb);end if;
 select coalesce(jsonb_agg(jsonb_build_object('id',f.id,'name',f.name,'files',coalesce((
   select jsonb_agg(jsonb_build_object('id',w.id,'name',coalesce(m.display_name,w.name),'mimeType',w.mime_type,'sizeBytes',w.size_bytes,'sha256',w.sha256,'createdAt',w.created_at) order by lower(coalesce(m.display_name,w.name)),w.id)
   from public.pro_work_file_meta m join public.pro_work_files w on w.owner_id=m.owner_id and w.id=m.file_id
   where m.owner_id=owner and m.folder_id=f.id and m.trashed_at is null and w.ready),'[]'::jsonb)) order by lower(f.name),f.id),'[]'::jsonb) into folders
 from public.pro_work_file_folders f where f.owner_id=owner and f.work_id=wid and f.client_visible and not public.pro_wfo_folder_trashed(owner,f.id);
 return jsonb_build_object('folders',folders);
end $$;
create or replace function public.pro_work_file_folder_client_download(p_actor uuid,p_request uuid,p_file uuid) returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare owner uuid;wid text;w public.pro_work_files;m public.pro_work_file_meta;
begin
 if not exists(select 1 from public.profiles where id=p_actor and not coalesce(is_disabled,false)) then raise exception 'Forbidden' using errcode='42501';end if;
 select owner_id,work_id into owner,wid from public.pro_appointment_requests where id=p_request and client_user_id=p_actor and work_id is not null;
 if not found or not public.pro_wfv_client_files_visible(owner,wid) then return null;end if;
 select * into w from public.pro_work_files where owner_id=owner and work_id=wid and id=p_file and ready;if not found then return null;end if;
 select * into m from public.pro_work_file_meta where owner_id=owner and file_id=p_file and trashed_at is null;if not found or m.folder_id is null then return null;end if;
 if not exists(select 1 from public.pro_work_file_folders f where f.owner_id=owner and f.id=m.folder_id and f.client_visible) or public.pro_wfo_folder_trashed(owner,m.folder_id) then return null;end if;
 return jsonb_build_object('objectPath',w.object_path,'name',w.name,'displayName',coalesce(m.display_name,w.name),'mimeType',w.mime_type,'sizeBytes',w.size_bytes,'sha256',w.sha256);
end $$;

-- ===================================================================== 5. library tags
create table if not exists public.pro_company_file_tags(
 owner_id uuid not null,file_id uuid not null,
 tag text not null check(length(tag) between 1 and 30 and tag=btrim(tag) and tag=lower(tag) and tag !~ '[[:cntrl:]/,]' and position(chr(92) in tag)=0),
 created_at timestamptz not null default clock_timestamp(),
 primary key(owner_id,file_id,tag),foreign key(owner_id,file_id) references public.pro_company_files(owner_id,id) on delete cascade);
create index if not exists pro_company_file_tags_tag on public.pro_company_file_tags(owner_id,tag);
create table if not exists public.pro_company_file_tag_actions(
 owner_id uuid not null,action_id uuid not null,input_hash text not null,before_tags jsonb not null,result jsonb not null,at timestamptz not null default clock_timestamp(),
 primary key(owner_id,action_id));
create or replace function public.pro_company_file_tags_of(p_owner uuid,p_file uuid) returns jsonb language sql stable security invoker set search_path=public,pg_temp as $$
 select coalesce(jsonb_agg(tag order by tag),'[]'::jsonb) from public.pro_company_file_tags where owner_id=p_owner and file_id=p_file $$;
create or replace function public.pro_company_file_tags_read(p_actor uuid,p_tag text default null) returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare want text:=nullif(lower(btrim(coalesce(p_tag,''))),'');
begin
 if not coalesce(public.pro_appointment_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;
 if length(want)>30 then raise exception 'Invalid tag' using errcode='22023';end if;
 return jsonb_build_object(
  'tags',coalesce((select jsonb_agg(jsonb_build_object('tag',x.tag,'count',x.n) order by x.tag) from(select t.tag,count(*) n from public.pro_company_file_tags t join public.pro_company_files f on f.owner_id=t.owner_id and f.id=t.file_id where t.owner_id=p_actor and f.ready and not f.archived and not public.pro_cfv_hidden(p_actor,f.id) group by t.tag) x),'[]'::jsonb),
  'fileTags',coalesce((select jsonb_object_agg(x.file_id::text,x.tags) from(select file_id,jsonb_agg(tag order by tag) tags from public.pro_company_file_tags where owner_id=p_actor group by file_id) x),'{}'::jsonb),
  'files',case when want is null then '[]'::jsonb else coalesce((select jsonb_agg(public.pro_company_file_json(f) order by lower(f.name),f.id) from public.pro_company_files f join public.pro_company_file_tags t on t.owner_id=f.owner_id and t.file_id=f.id and t.tag=want where f.owner_id=p_actor and f.ready and not f.archived and not public.pro_cfv_hidden(p_actor,f.id)),'[]'::jsonb) end,
  'tag',want);
end $$;
create or replace function public.pro_company_file_tags_mutate(p_actor uuid,p_input jsonb) returns jsonb
language plpgsql security invoker set search_path=public,pg_temp as $$
declare keys text[];aid uuid;fid uuid;hash text:=md5(p_input::text);prior public.pro_company_file_tag_actions;want text[];before_tags jsonb;answer jsonb;t text;
begin
 if not coalesce(public.pro_appointment_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;
 if jsonb_typeof(p_input) is distinct from 'object' then raise exception 'Invalid tags' using errcode='22023';end if;
 select array_agg(k order by k) into keys from jsonb_object_keys(p_input) k;
 if keys is distinct from array['action','actionId','fileId','tags'] or p_input->>'action' is distinct from 'set_tags' or jsonb_typeof(p_input->'tags') is distinct from 'array' or jsonb_array_length(p_input->'tags')>6 then raise exception 'Invalid tags' using errcode='22023';end if;
 begin aid:=(p_input->>'actionId')::uuid;fid:=(p_input->>'fileId')::uuid;exception when others then raise exception 'Invalid tags' using errcode='22023';end;
 if exists(select 1 from jsonb_array_elements(p_input->'tags') e where jsonb_typeof(e) is distinct from 'string') then raise exception 'Invalid tags' using errcode='22023';end if;
 select coalesce(array_agg(distinct lower(btrim(e))),'{}') into want from jsonb_array_elements_text(p_input->'tags') e;
 foreach t in array want loop if length(t) not between 1 and 30 or t ~ '[[:cntrl:]/,]' or position(chr(92) in t)>0 then raise exception 'Invalid tag' using errcode='22023';end if;end loop;
 perform pg_advisory_xact_lock(hashtextextended('pro-company-file-tags:'||p_actor::text,0));
 select * into prior from public.pro_company_file_tag_actions where owner_id=p_actor and action_id=aid;
 if found then if prior.input_hash<>hash then raise exception 'Action id reused' using errcode='22023';end if;return prior.result||jsonb_build_object('replayed',true);end if;
 if not exists(select 1 from public.pro_company_files where owner_id=p_actor and id=fid and ready and not archived) then raise exception 'File unavailable' using errcode='40001';end if;
 before_tags:=public.pro_company_file_tags_of(p_actor,fid);
 delete from public.pro_company_file_tags where owner_id=p_actor and file_id=fid and not tag=any(want);
 insert into public.pro_company_file_tags(owner_id,file_id,tag) select p_actor,fid,x from unnest(want) x on conflict do nothing;
 answer:=jsonb_build_object('fileId',fid,'tags',public.pro_company_file_tags_of(p_actor,fid));
 insert into public.pro_company_file_tag_actions(owner_id,action_id,input_hash,before_tags,result) values(p_actor,aid,hash,before_tags,answer);
 return answer;
end $$;
create or replace function public.pro_company_file_tag_actions_immutable() returns trigger language plpgsql security invoker set search_path=public,pg_temp as $$
begin raise exception 'Tag receipts are immutable' using errcode='23514';end $$;
drop trigger if exists pro_company_file_tag_actions_immutable on public.pro_company_file_tag_actions;
create trigger pro_company_file_tag_actions_immutable before update or delete on public.pro_company_file_tag_actions for each row when (pg_trigger_depth()=0) execute function public.pro_company_file_tag_actions_immutable();

-- ===================================================================== grants and buckets
do $$declare t text;f record;begin
 foreach t in array array['pro_company_file_tags','pro_company_file_tag_actions'] loop
  execute format('alter table public.%I enable row level security',t);execute format('revoke all on public.%I from public,anon,authenticated',t);execute format('grant select,insert,update,delete on public.%I to service_role',t);end loop;
 for f in select p.oid::regprocedure sig from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in('pro_file_doc_ext','pro_file_quota_used','pro_file_quota_check','pro_file_quota_read','pro_work_file_reserve','pro_company_files_mutate','pro_wfo_file_in_use','pro_wfo_folder_json','pro_work_file_organizer_mutate','pro_work_file_folders_client_read','pro_work_file_folder_client_download','pro_company_file_tags_of','pro_company_file_tags_read','pro_company_file_tags_mutate','pro_company_file_tag_actions_immutable') loop
  execute format('revoke all on function %s from public,anon,authenticated',f.sig);execute format('grant execute on function %s to service_role',f.sig);end loop;
 if to_regclass('storage.buckets') is not null then
  update storage.buckets set allowed_mime_types=array['image/jpeg','application/pdf','application/vnd.openxmlformats-officedocument.wordprocessingml.document','application/vnd.openxmlformats-officedocument.spreadsheetml.sheet','application/vnd.openxmlformats-officedocument.presentationml.presentation','text/csv','text/plain','image/vnd.dwg','image/vnd.dxf','image/heic','video/mp4','video/quicktime'] where id in('pro-work-files','pro-company-files');
  if exists(select 1 from storage.buckets where id in('pro-work-files','pro-company-files') and (public or file_size_limit is distinct from 20971520 or cardinality(allowed_mime_types)<>12)) then raise exception 'File buckets must stay private with 20 MiB and the document formats';end if;
 end if;
end $$;
commit;
notify pgrst,'reload schema';

-- ===== sales-pipeline-forecast-local.sql =====
-- LOCAL PRO ONLY. Ronda F2-B (2026-11-19), Sales pipeline (Houzz Pro parity rows 07 and 08).
--  * Stage appearance and probability (row 07): per company stage colour (fixed palette keys, never raw CSS)
--    and win probability 0-100 used for the weighted forecast. Stage creation/rename/reorder/hide/retire with
--    reassignment of existing leads stays in request-pipeline / lead-private-stages (same catalogue, untouched).
--    Writes: CAS on a per-company revision (40001), idempotent actionId receipts, immutable history.
--  * Stage spans (rows 07 and 08): a record of when each lead entered and left each stage. The existing stage
--    writers keep their tables; AFTER INSERT triggers on their history tables only append a "mark" (lead, time
--    and the explicit stage when known). pro_lead_stage_observe() turns marks into spans and closes/opens a
--    span when the effective stage (also automatic projection: shared quote, converted job...) differs from the
--    open one. Leads that existed before this module get one span "since the last recorded stage change"
--    (source backfill). Spans are never deleted; only left_at may be set once.
--  * Forecast and funnel readers: open value and weighted value per stage and currency (manual opportunities
--    with an expected revenue; lost outcomes and archived leads excluded), time in stage, funnel by stage
--    reached (spans + current stage + explicit job conversion) with conversion % for a Costa Rica period.
-- Patterns: RLS on, service_role only, security invoker. Nothing is sent; no third party is called.
begin;
create table if not exists public.pro_lead_stage_style_heads(
 owner_id uuid primary key references public.profiles(id) on delete cascade,revision integer not null check(revision between 0 and 2147483646));
create table if not exists public.pro_lead_stage_styles(
 owner_id uuid not null references public.profiles(id) on delete cascade,stage_id text not null check(length(stage_id) between 1 and 80),
 color text not null check(color in('slate','blue','cyan','teal','green','lime','amber','orange','red','pink','violet','indigo')),
 probability integer not null check(probability between 0 and 100),updated_at timestamptz not null default clock_timestamp(),primary key(owner_id,stage_id));
create table if not exists public.pro_lead_stage_style_actions(
 owner_id uuid not null references public.profiles(id) on delete cascade,action_id uuid not null,input jsonb not null,result jsonb not null,
 at timestamptz not null default clock_timestamp(),primary key(owner_id,action_id));
create table if not exists public.pro_lead_stage_style_history(
 owner_id uuid not null references public.profiles(id) on delete cascade,action_id uuid not null,stage_id text not null,
 action text not null check(action in('style','reset')),before_value jsonb not null,after_value jsonb not null,actor_name text not null default '',
 at timestamptz not null default clock_timestamp(),primary key(owner_id,action_id));
create table if not exists public.pro_lead_stage_marks(
 mark_id bigint generated always as identity primary key,owner_id uuid not null references public.profiles(id) on delete cascade,
 kind text not null check(kind in('manual','request')),lead_id uuid not null,action text not null check(length(action) between 1 and 40),
 stage_id text,at timestamptz not null);
create index if not exists pro_lead_stage_marks_owner on public.pro_lead_stage_marks(owner_id,mark_id);
create table if not exists public.pro_lead_stage_cursors(
 owner_id uuid primary key references public.profiles(id) on delete cascade,last_mark bigint not null default 0,observed_at timestamptz);
create table if not exists public.pro_lead_stage_spans(
 owner_id uuid not null references public.profiles(id) on delete cascade,kind text not null check(kind in('manual','request')),lead_id uuid not null,
 seq integer not null check(seq between 1 and 100000),stage_id text not null,entered_at timestamptz not null,left_at timestamptz,
 source text not null check(source in('created','moved','observed','backfill')),primary key(owner_id,kind,lead_id,seq),check(left_at is null or left_at>=entered_at));
create unique index if not exists pro_lead_stage_spans_open on public.pro_lead_stage_spans(owner_id,kind,lead_id) where left_at is null;

do $$declare t text;begin
 foreach t in array array['pro_lead_stage_style_heads','pro_lead_stage_styles','pro_lead_stage_style_actions','pro_lead_stage_style_history','pro_lead_stage_marks','pro_lead_stage_cursors','pro_lead_stage_spans'] loop
  execute format('alter table public.%I enable row level security',t);execute format('revoke all on table public.%I from public,anon,authenticated',t);execute format('grant all on table public.%I to service_role',t);
 end loop;
end $$;

-- Receipts, history and marks are immutable; a span may only be closed once (left_at null -> value).
create or replace function public.pro_lead_stage_immutable() returns trigger language plpgsql security invoker set search_path=public,pg_temp as $$
begin
 if tg_table_name='pro_lead_stage_spans' and tg_op='UPDATE' then
  if to_jsonb(old)->'left_at'='null'::jsonb and to_jsonb(new)->'left_at'<>'null'::jsonb and(to_jsonb(new)-'left_at')=(to_jsonb(old)-'left_at') then return new;end if;
 end if;
 raise exception 'Immutable record' using errcode='23514';
end $$;
do $$declare t text;begin
 foreach t in array array['pro_lead_stage_style_actions','pro_lead_stage_style_history','pro_lead_stage_marks','pro_lead_stage_spans'] loop
  execute format('drop trigger if exists %I on public.%I',t||'_immutable',t);
  execute format('create trigger %I before update or delete on public.%I for each row when (pg_trigger_depth()=0) execute function public.pro_lead_stage_immutable()',t||'_immutable',t);
 end loop;
end $$;

-- ===== Marks from the existing stage writers (append only; never breaks the writer) =====
create or replace function public.pro_lead_stage_mark_center() returns trigger language plpgsql security invoker set search_path=public,pg_temp as $$
begin
 if new.kind='manual' and new.action in('create','set_stage','return_auto','reassign_stage','restore') then
  begin
   insert into public.pro_lead_stage_marks(owner_id,kind,lead_id,action,stage_id,at)
   values(new.owner_id,'manual',new.id,new.action,case when new.after_item->'manual'->>'stageMode'='manual' then new.after_item->'manual'->>'stageId' end,new.at);
  exception when others then null;
  end;
 end if;
 return null;
end $$;
create or replace function public.pro_lead_stage_mark_request() returns trigger language plpgsql security invoker set search_path=public,pg_temp as $$
begin
 begin
  insert into public.pro_lead_stage_marks(owner_id,kind,lead_id,action,stage_id,at)
  values(new.owner_id,'request',new.request_id,new.action,case when new.after_state->>'mode'='manual' then new.after_state->>'stageId' end,new.at);
 exception when others then null;
 end;
 return null;
end $$;
drop trigger if exists pro_lead_stage_mark_center on public.pro_lead_center_history;
create trigger pro_lead_stage_mark_center after insert on public.pro_lead_center_history for each row execute function public.pro_lead_stage_mark_center();
drop trigger if exists pro_lead_stage_mark_request on public.pro_request_pipeline_history;
create trigger pro_lead_stage_mark_request after insert on public.pro_request_pipeline_history for each row execute function public.pro_lead_stage_mark_request();

-- ===== Stage settings (catalogue + colour/probability, defaults when not customized) =====
create or replace function public.pro_lead_stage_default_color(p_stage text) returns text language sql immutable security invoker set search_path=public,pg_temp as $$
 select case p_stage when 'new' then 'blue' when 'followed_up' then 'cyan' when 'connected' then 'teal' when 'meeting_scheduled' then 'violet' when 'estimate_sent' then 'amber' when 'won' then 'green' else 'slate' end $$;
create or replace function public.pro_lead_stage_default_probability(p_stage text) returns integer language sql immutable security invoker set search_path=public,pg_temp as $$
 select case p_stage when 'new' then 10 when 'followed_up' then 20 when 'connected' then 30 when 'meeting_scheduled' then 50 when 'estimate_sent' then 70 when 'won' then 100 else 40 end $$;
create or replace function public.pro_lead_stage_settings(p_owner uuid) returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare catalog jsonb;begin
 perform public.pro_lead_origin_owner(p_owner);catalog:=public.pro_lead_origin_stage_catalog(p_owner);
 return jsonb_build_object('revision',coalesce((select revision from public.pro_lead_stage_style_heads where owner_id=p_owner),0),'catalogRevision',(catalog->>'revision')::integer,
  'stages',coalesce((select jsonb_agg(jsonb_build_object('id',st->>'id','builtin',(st->>'builtin')::boolean,'name',st->'name','position',(st->>'position')::integer,'hidden',coalesce((st->>'hidden')::boolean,false),
    'color',coalesce(s.color,public.pro_lead_stage_default_color(st->>'id')),'probability',coalesce(s.probability,public.pro_lead_stage_default_probability(st->>'id')),'customized',s.stage_id is not null) order by(st->>'position')::integer)
   from jsonb_array_elements(catalog->'stages') st left join public.pro_lead_stage_styles s on s.owner_id=p_owner and s.stage_id=st->>'id'),'[]'::jsonb));
end $$;

create or replace function public.pro_lead_stage_style_mutate(p_owner uuid,p_input jsonb,p_member uuid default null) returns jsonb language plpgsql security invoker set search_path=public,pg_temp as $$
declare act text;keys text[];aid uuid;receipt public.pro_lead_stage_style_actions;cur integer;sid text;before_json jsonb;after_json jsonb;answer jsonb;settings jsonb;
begin
 perform public.pro_lead_origin_owner(p_owner);
 if jsonb_typeof(p_input) is distinct from 'object' then raise exception 'Invalid stage settings' using errcode='22023';end if;
 act:=p_input->>'action';select array_agg(x order by x) into keys from jsonb_object_keys(p_input) x;
 if keys is distinct from(case act when 'style' then array['action','actionId','color','probability','revision','stageId'] when 'reset' then array['action','actionId','revision','stageId'] end)
  or jsonb_typeof(p_input->'revision') is distinct from 'number' or not coalesce(p_input->>'revision'~'^[0-9]{1,10}$',false) or(p_input->>'revision')::numeric>2147483645
  or jsonb_typeof(p_input->'stageId') is distinct from 'string' then raise exception 'Unexpected stage settings fields' using errcode='22023';end if;
 if act='style' and(jsonb_typeof(p_input->'color') is distinct from 'string' or p_input->>'color' not in('slate','blue','cyan','teal','green','lime','amber','orange','red','pink','violet','indigo')
  or jsonb_typeof(p_input->'probability') is distinct from 'number' or not coalesce(p_input->>'probability'~'^[0-9]{1,3}$',false) or(p_input->>'probability')::integer>100) then raise exception 'Invalid colour or probability' using errcode='22023';end if;
 begin aid:=(p_input->>'actionId')::uuid;exception when others then raise exception 'Invalid identity' using errcode='22023';end;
 perform pg_advisory_xact_lock(hashtextextended('pro-lead-stage-style:'||p_owner::text,0));
 select * into receipt from public.pro_lead_stage_style_actions where owner_id=p_owner and action_id=aid;
 if found then if receipt.input is distinct from p_input then raise exception 'Action id reused' using errcode='22023';end if;return receipt.result||jsonb_build_object('replayed',true);end if;
 cur:=coalesce((select revision from public.pro_lead_stage_style_heads where owner_id=p_owner),0);
 if cur<>(p_input->>'revision')::integer then raise exception 'Stage settings changed' using errcode='40001';end if;
 sid:=p_input->>'stageId';settings:=public.pro_lead_stage_settings(p_owner);
 select x into before_json from jsonb_array_elements(settings->'stages') x where x->>'id'=sid;
 if before_json is null then raise exception 'Stage unavailable' using errcode='P0002';end if;
 if act='style' then
  insert into public.pro_lead_stage_styles(owner_id,stage_id,color,probability) values(p_owner,sid,p_input->>'color',(p_input->>'probability')::integer)
  on conflict(owner_id,stage_id) do update set color=excluded.color,probability=excluded.probability,updated_at=clock_timestamp();
 else delete from public.pro_lead_stage_styles where owner_id=p_owner and stage_id=sid;end if;
 insert into public.pro_lead_stage_style_heads(owner_id,revision) values(p_owner,cur+1) on conflict(owner_id) do update set revision=excluded.revision;
 settings:=public.pro_lead_stage_settings(p_owner);select x into after_json from jsonb_array_elements(settings->'stages') x where x->>'id'=sid;
 answer:=jsonb_build_object('action',act,'revision',cur+1,'stage',after_json);
 insert into public.pro_lead_stage_style_history(owner_id,action_id,stage_id,action,before_value,after_value,actor_name)
 values(p_owner,aid,sid,act,before_json,after_json,left(coalesce(public.pro_team_name(case when p_member is not null and public.pro_role_of(p_member,p_owner) is not null then p_member else p_owner end),''),160));
 insert into public.pro_lead_stage_style_actions(owner_id,action_id,input,result) values(p_owner,aid,p_input,answer);
 return answer;
end $$;

-- ===== Observation: marks + effective stage -> spans =====
create or replace function public.pro_lead_stage_observe(p_owner uuid) returns integer language plpgsql security invoker set search_path=public,pg_temp as $$
declare cursor_from bigint;cursor_to bigint;lead record;m record;open_span public.pro_lead_stage_spans;changes integer:=0;create_id bigint;create_stage text;last_auto timestamptz;since timestamptz;next_seq integer;
begin
 perform public.pro_lead_origin_owner(p_owner);
 perform pg_advisory_xact_lock(hashtextextended('pro-lead-stage-observe:'||p_owner::text,0));
 insert into public.pro_lead_stage_cursors(owner_id) values(p_owner) on conflict do nothing;
 select last_mark into cursor_from from public.pro_lead_stage_cursors where owner_id=p_owner for update;
 select coalesce(max(mark_id),cursor_from) into cursor_to from public.pro_lead_stage_marks where owner_id=p_owner and mark_id>cursor_from;
 for lead in select s.kind,s.id,s.created_at,s.effective_stage from public.pro_lead_inbox_sources(p_owner,'') s loop
  select * into open_span from public.pro_lead_stage_spans where owner_id=p_owner and kind=lead.kind and lead_id=lead.id and left_at is null;
  if open_span.lead_id is null then
   select mk.mark_id,mk.stage_id into create_id,create_stage from public.pro_lead_stage_marks mk where mk.owner_id=p_owner and mk.kind=lead.kind and mk.lead_id=lead.id and mk.action='create' and mk.mark_id>cursor_from and mk.mark_id<=cursor_to order by mk.mark_id limit 1;
   next_seq:=coalesce((select max(seq) from public.pro_lead_stage_spans where owner_id=p_owner and kind=lead.kind and lead_id=lead.id),0)+1;
   if create_id is not null then
    insert into public.pro_lead_stage_spans(owner_id,kind,lead_id,seq,stage_id,entered_at,source) values(p_owner,lead.kind,lead.id,next_seq,coalesce(create_stage,'new'),lead.created_at,'created') returning * into open_span;
   else
    -- First observation of a lead that existed before (or a ContrataCR request): one span since the last recorded stage change.
    since:=greatest(lead.created_at,coalesce((select max(h.at) from public.pro_lead_center_history h where h.owner_id=p_owner and h.kind=lead.kind and h.id=lead.id and h.action in('set_stage','return_auto','reassign_stage')),lead.created_at),
     coalesce((select max(h.at) from public.pro_request_pipeline_history h where lead.kind='request' and h.owner_id=p_owner and h.request_id=lead.id),lead.created_at));
    insert into public.pro_lead_stage_spans(owner_id,kind,lead_id,seq,stage_id,entered_at,source) values(p_owner,lead.kind,lead.id,next_seq,lead.effective_stage,least(since,now()),case when lead.created_at>=coalesce((select min(at) from public.pro_lead_stage_marks where owner_id=p_owner),now()) then 'created' else 'backfill' end);
    changes:=changes+1;continue;
   end if;
   changes:=changes+1;
  end if;
  last_auto:=null;
  for m in select * from public.pro_lead_stage_marks where owner_id=p_owner and kind=lead.kind and lead_id=lead.id and mark_id>cursor_from and mark_id<=cursor_to and(create_id is null or mark_id>create_id) order by mark_id loop
   if m.stage_id is null then last_auto:=greatest(m.at,open_span.entered_at);continue;end if;
   last_auto:=null;
   if m.stage_id<>open_span.stage_id then
    update public.pro_lead_stage_spans set left_at=greatest(m.at,open_span.entered_at) where owner_id=p_owner and kind=lead.kind and lead_id=lead.id and seq=open_span.seq;
    insert into public.pro_lead_stage_spans(owner_id,kind,lead_id,seq,stage_id,entered_at,source) values(p_owner,lead.kind,lead.id,open_span.seq+1,m.stage_id,greatest(m.at,open_span.entered_at),'moved') returning * into open_span;
    changes:=changes+1;
   end if;
  end loop;
  create_id:=null;create_stage:=null;
  if lead.effective_stage<>open_span.stage_id then
   since:=greatest(coalesce(last_auto,now()),open_span.entered_at);
   update public.pro_lead_stage_spans set left_at=since where owner_id=p_owner and kind=lead.kind and lead_id=lead.id and seq=open_span.seq;
   insert into public.pro_lead_stage_spans(owner_id,kind,lead_id,seq,stage_id,entered_at,source) values(p_owner,lead.kind,lead.id,open_span.seq+1,lead.effective_stage,since,case when last_auto is null then 'observed' else 'moved' end);
   changes:=changes+1;
  end if;
 end loop;
 update public.pro_lead_stage_cursors set last_mark=cursor_to,observed_at=now() where owner_id=p_owner;
 return changes;
end $$;

-- ===== Readers (they observe first, so they are volatile) =====
create or replace function public.pro_lead_pipeline_converted(p_owner uuid,p_kind text,p_id uuid) returns boolean language sql stable security invoker set search_path=public,pg_temp as $$
 select case when p_kind='manual' then exists(select 1 from public.pro_manual_lead_works m join public.pro_work w on w.user_id=m.owner_id and w.id=m.work_id_text and w."clientId"=m.source_client_id and w."bookingClientId" is null where m.owner_id=p_owner and m.lead_kind='manual' and m.lead_id=p_id)
  else exists(select 1 from public.pro_appointment_requests q join public.pro_work w on w.user_id=p_owner and w.id=q.work_id where q.owner_id=p_owner and q.id=p_id and not w.cancelled) end $$;

create or replace function public.pro_lead_pipeline_read(p_owner uuid,p_query jsonb) returns jsonb language plpgsql security invoker set search_path=public,pg_temp as $$
declare v text;keys text[];settings jsonb;answer jsonb;p_from date;p_to date;p_channel text;k text;lid uuid;
begin
 perform public.pro_lead_origin_owner(p_owner);
 if jsonb_typeof(p_query) is distinct from 'object' then raise exception 'Invalid pipeline query' using errcode='22023';end if;
 v:=p_query->>'view';select array_agg(x order by x) into keys from jsonb_object_keys(p_query) x;
 if keys is distinct from(case v when 'settings' then array['view'] when 'forecast' then array['view'] when 'lead' then array['id','kind','view'] when 'funnel' then array['channel','from','to','view'] end) then raise exception 'Unexpected pipeline query' using errcode='22023';end if;
 settings:=public.pro_lead_stage_settings(p_owner);
 if v='settings' then return settings;end if;
 perform public.pro_lead_stage_observe(p_owner);
 if v='lead' then
  k:=p_query->>'kind';begin lid:=(p_query->>'id')::uuid;exception when others then raise exception 'Invalid identity' using errcode='22023';end;
  if k not in('manual','request') then raise exception 'Invalid lead source' using errcode='22023';end if;
  if not exists(select 1 from public.pro_lead_inbox_sources(p_owner,'') s where s.kind=k and s.id=lid) then raise exception 'Lead unavailable' using errcode='P0002';end if;
  return jsonb_build_object('kind',k,'id',lid,'spans',coalesce((select jsonb_agg(jsonb_build_object('seq',s.seq,'stageId',s.stage_id,'enteredAt',s.entered_at,'leftAt',s.left_at,
    'hours',round((extract(epoch from coalesce(s.left_at,now())-s.entered_at)/3600.0)::numeric,1),'source',s.source) order by s.seq) from public.pro_lead_stage_spans s where s.owner_id=p_owner and s.kind=k and s.lead_id=lid),'[]'::jsonb));
 end if;
 if v='forecast' then
  with st as(select x->>'id' id,(x->>'position')::integer pos,(x->>'probability')::integer prob,coalesce((x->>'hidden')::boolean,false) hidden from jsonb_array_elements(settings->'stages') x),
  src as materialized(select s.kind,s.id,s.effective_stage,l.currency,l.revenue_cents,o.outcome,sp.entered_at
   from public.pro_lead_inbox_sources(p_owner,'') s left join public.pro_lead_center_records l on s.kind='manual' and l.owner_id=p_owner and l.kind='manual' and l.id=s.id
   left join public.pro_lead_outcomes o on o.owner_id=p_owner and o.kind=s.kind and o.lead_id=s.id
   left join public.pro_lead_stage_spans sp on sp.owner_id=p_owner and sp.kind=s.kind and sp.lead_id=s.id and sp.left_at is null
   where not s.archived and coalesce(o.outcome,'')<>'lost'),
  money as(select src.effective_stage,src.currency,sum(src.revenue_cents) total,sum(round(src.revenue_cents*st.prob/100.0)) weighted,count(*) n from src join st on st.id=src.effective_stage where src.revenue_cents is not null and src.currency is not null group by 1,2)
  select jsonb_build_object('revision',settings->'revision',
   'stages',coalesce((select jsonb_agg(jsonb_build_object('stageId',st.id,'probability',st.prob,'count',(select count(*) from src where src.effective_stage=st.id),
     'withValue',coalesce((select sum(n) from money where money.effective_stage=st.id),0),
     'avgHours',(select round(avg(extract(epoch from now()-src.entered_at)/3600.0)::numeric,1) from src where src.effective_stage=st.id and src.entered_at is not null),
     'values',coalesce((select jsonb_agg(jsonb_build_object('currency',money.currency,'totalCents',money.total,'weightedCents',money.weighted) order by money.currency) from money where money.effective_stage=st.id),'[]'::jsonb)) order by st.pos) from st where not st.hidden),'[]'::jsonb),
   'totals',coalesce((select jsonb_agg(jsonb_build_object('currency',c.currency,'openCents',c.open_total,'weightedCents',c.open_weighted,'wonCents',c.won_total) order by c.currency)
     from(select currency,coalesce(sum(total) filter(where effective_stage<>'won'),0) open_total,coalesce(sum(weighted) filter(where effective_stage<>'won'),0) open_weighted,coalesce(sum(total) filter(where effective_stage='won'),0) won_total from money group by currency) c),'[]'::jsonb),
   'withoutValue',(select count(*) from src where src.revenue_cents is null or src.currency is null))
  into answer;
  return answer;
 end if;
 -- funnel
 if jsonb_typeof(p_query->'from') is distinct from 'string' or jsonb_typeof(p_query->'to') is distinct from 'string' or jsonb_typeof(p_query->'channel') not in('string','null') or length(coalesce(p_query->>'channel',''))>40 then raise exception 'Invalid funnel query' using errcode='22023';end if;
 begin p_from:=(p_query->>'from')::date;p_to:=(p_query->>'to')::date;exception when others then raise exception 'Invalid funnel period' using errcode='22023';end;
 if p_from>p_to or p_to-p_from>3660 or p_from<date'1900-01-01' or p_to>date'2100-12-31' then raise exception 'Invalid funnel period' using errcode='22023';end if;
 p_channel:=p_query->>'channel';
 with st as(select x->>'id' id,(x->>'position')::integer pos,coalesce((x->>'hidden')::boolean,false) hidden from jsonb_array_elements(settings->'stages') x),
 base as materialized(select s.kind,s.id,s.effective_stage,o.outcome,public.pro_lead_pipeline_converted(p_owner,s.kind,s.id) converted,(select pos from st where st.id=s.effective_stage) cur_pos
  from public.pro_lead_inbox_sources(p_owner,'') s left join public.pro_lead_outcomes o on o.owner_id=p_owner and o.kind=s.kind and o.lead_id=s.id
  where s.created_day between p_from and p_to and(p_channel is null or p_channel='unspecified' and s.channel_id is null or s.channel_id=p_channel)),
 reached as(select b.kind,b.id,greatest(coalesce(b.cur_pos,0),coalesce((select max(st.pos) from public.pro_lead_stage_spans sp join st on st.id=sp.stage_id where sp.owner_id=p_owner and sp.kind=b.kind and sp.lead_id=b.id),0),
   case when b.converted then(select pos from st where st.id='won') else 0 end) maxpos from base b),
 dur as(select sp.stage_id,extract(epoch from coalesce(sp.left_at,now())-sp.entered_at)/3600.0 hours,sp.left_at is null open from public.pro_lead_stage_spans sp join base b on b.kind=sp.kind and b.id=sp.lead_id where sp.owner_id=p_owner),
 stage_rows as(select st.id,st.pos,(select count(*) from reached r where r.maxpos>=st.pos) reached,(select count(*) from base where base.effective_stage=st.id) current,
   (select round(avg(hours)::numeric,1) from dur where dur.stage_id=st.id) avg_hours,(select round((percentile_cont(0.5) within group(order by hours))::numeric,1) from dur where dur.stage_id=st.id) median_hours,
   (select count(*) from dur where dur.stage_id=st.id and not dur.open) completed from st where not st.hidden),
 rows2 as(select r.*,lag(r.reached) over(order by r.pos) prev from stage_rows r)
 select jsonb_build_object('from',to_char(p_from,'YYYY-MM-DD'),'to',to_char(p_to,'YYYY-MM-DD'),'channel',p_channel,
  'received',(select count(*) from base),'won',(select count(*) from base where effective_stage='won' or outcome='won' or converted),'lost',(select count(*) from base where outcome='lost'),'converted',(select count(*) from base where converted),
  'observedSince',(select min(entered_at) from public.pro_lead_stage_spans where owner_id=p_owner and source<>'backfill'),
  'backfilled',(select count(*) from public.pro_lead_stage_spans sp join base b on b.kind=sp.kind and b.id=sp.lead_id where sp.owner_id=p_owner and sp.source='backfill'),
  'stages',coalesce((select jsonb_agg(jsonb_build_object('stageId',r.id,'reached',r.reached,'current',r.current,'avgHours',r.avg_hours,'medianHours',r.median_hours,'completedSpans',r.completed,
    'fromStart',case when(select count(*) from base)=0 then null else round(r.reached*100.0/(select count(*) from base),1) end,
    'fromPrevious',case when r.prev is null or r.prev=0 then null else round(r.reached*100.0/r.prev,1) end) order by r.pos) from rows2 r),'[]'::jsonb))
 into answer;
 return answer;
end $$;

do $$declare f record;begin
 for f in select p.oid::regprocedure sig from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in(
  'pro_lead_stage_immutable','pro_lead_stage_mark_center','pro_lead_stage_mark_request','pro_lead_stage_default_color','pro_lead_stage_default_probability','pro_lead_stage_settings',
  'pro_lead_stage_style_mutate','pro_lead_stage_observe','pro_lead_pipeline_converted','pro_lead_pipeline_read') loop
  execute format('revoke all on function %s from public,anon,authenticated',f.sig);execute format('grant execute on function %s to service_role',f.sig);end loop;
end $$;
commit;
notify pgrst,'reload schema';

-- ===== estimate-proposals-local.sql =====
-- LOCAL PRO ONLY. Ronda F2-B (2026-11-19), visual proposal (Houzz Pro parity row 39).
-- A private estimate gets a proposal design: cover title, introduction, closing words and photos taken from
-- the company's EXISTING files (Archivos de la empresa) or job files (JPEG only): one cover photo, up to six per
-- section and up to six per line. Nothing is uploaded or copied here; the design only references files.
-- The design is applied explicitly to a shared version ("publish"): an immutable snapshot per publication and
-- sequence. The customer sees the last snapshot of the version together with the existing per-line approval
-- (quote-line-decisions); once the version is accepted, declined, withdrawn or superseded the design is frozen.
-- Photos are served only to the owner or the version's recipient and only if listed in that snapshot; the
-- route verifies size and SHA-256 of the stored bytes.
-- Patterns: RLS on, service_role only, security invoker, CAS 40001, idempotent actionId receipts, immutable
-- history and snapshots. Nothing is sent; no third party is called.
begin;
create table if not exists public.pro_estimate_proposals(
 owner_id uuid not null,estimate_id uuid not null,revision integer not null check(revision between 1 and 2147483646),
 cover_title text not null default '' check(length(cover_title)<=120 and cover_title!~'[[:cntrl:]]'),
 intro text not null default '' check(length(intro)<=4000),closing text not null default '' check(length(closing)<=2000),
 updated_at timestamptz not null default clock_timestamp(),primary key(owner_id,estimate_id),
 foreign key(owner_id,estimate_id) references public.pro_private_estimates(owner_id,id) on delete cascade);
create table if not exists public.pro_estimate_proposal_images(
 owner_id uuid not null,estimate_id uuid not null,id uuid not null,target text not null check(target in('cover','section','line')),
 target_key text not null check(length(target_key)<=80),position integer not null check(position between 1 and 1000),
 source text not null check(source in('company','work')),file_id uuid not null,caption text not null default '' check(length(caption)<=160 and caption!~'[[:cntrl:]]'),
 created_at timestamptz not null default clock_timestamp(),primary key(owner_id,estimate_id,id),check((target='cover')=(target_key='')),
 foreign key(owner_id,estimate_id) references public.pro_estimate_proposals(owner_id,estimate_id) on delete cascade);
create table if not exists public.pro_estimate_proposal_actions(
 owner_id uuid not null references public.profiles(id) on delete cascade,action_id uuid not null,input jsonb not null,result jsonb not null,
 at timestamptz not null default clock_timestamp(),primary key(owner_id,action_id));
create table if not exists public.pro_estimate_proposal_history(
 owner_id uuid not null,estimate_id uuid not null,action_id uuid not null,action text not null check(action in('save','add_image','remove_image','move_image','publish')),
 before_value jsonb,after_value jsonb not null,at timestamptz not null default clock_timestamp(),primary key(owner_id,action_id),
 foreign key(owner_id,estimate_id) references public.pro_private_estimates(owner_id,id) on delete cascade);
create table if not exists public.pro_estimate_proposal_snapshots(
 publication_id uuid not null references public.pro_private_estimate_publications(id) on delete cascade,seq integer not null check(seq between 1 and 1000),
 owner_id uuid not null,proposal_revision integer not null,content jsonb not null check(jsonb_typeof(content)='object'),
 content_hash text not null check(content_hash~'^[a-f0-9]{64}$'),at timestamptz not null default clock_timestamp(),primary key(publication_id,seq));

do $$declare t text;begin
 foreach t in array array['pro_estimate_proposals','pro_estimate_proposal_images','pro_estimate_proposal_actions','pro_estimate_proposal_history','pro_estimate_proposal_snapshots'] loop
  execute format('alter table public.%I enable row level security',t);execute format('revoke all on table public.%I from public,anon,authenticated',t);execute format('grant all on table public.%I to service_role',t);
 end loop;
end $$;
create or replace function public.pro_estimate_proposal_immutable() returns trigger language plpgsql security invoker set search_path=public,pg_temp as $$
begin raise exception 'Immutable record' using errcode='23514';end $$;
do $$declare t text;begin
 foreach t in array array['pro_estimate_proposal_actions','pro_estimate_proposal_history','pro_estimate_proposal_snapshots'] loop
  execute format('drop trigger if exists %I on public.%I',t||'_immutable',t);
  execute format('create trigger %I before update or delete on public.%I for each row when (pg_trigger_depth()=0) execute function public.pro_estimate_proposal_immutable()',t||'_immutable',t);
 end loop;
end $$;

-- ===== Helpers =====
-- File reference of an eligible photo (JPEG, ready, not archived), or null.
create or replace function public.pro_estimate_proposal_file(p_owner uuid,p_source text,p_file uuid) returns jsonb language sql stable security invoker set search_path=public,pg_temp as $$
 select case p_source
  when 'company' then(select jsonb_build_object('bucket','pro-company-files','objectPath',f.object_path,'sha256',f.sha256,'sizeBytes',f.size_bytes,'name',f.name,'place',null) from public.pro_company_files f
   where f.owner_id=p_owner and f.id=p_file and f.mime_type='image/jpeg' and f.ready and not f.archived)
  when 'work' then(select jsonb_build_object('bucket','pro-work-files','objectPath',f.object_path,'sha256',f.sha256,'sizeBytes',f.size_bytes,'name',f.name,'place',w.service) from public.pro_work_files f
   left join public.pro_work w on w.user_id=f.owner_id and w.id=f.work_id where f.owner_id=p_owner and f.id=p_file and f.mime_type='image/jpeg' and f.ready)
 end $$;
create or replace function public.pro_estimate_proposal_owner(p_owner uuid,p_estimate uuid) returns void language plpgsql stable security invoker set search_path=public,pg_temp as $$
begin
 if not coalesce(public.pro_private_work_tools_enabled(p_owner),false) then raise exception 'Forbidden' using errcode='42501';end if;
 if not exists(select 1 from public.pro_private_estimates where owner_id=p_owner and id=p_estimate) then raise exception 'Estimate unavailable' using errcode='P0002';end if;
end $$;
create or replace function public.pro_estimate_proposal_json(p_owner uuid,p_estimate uuid) returns jsonb language sql stable security invoker set search_path=public,pg_temp as $$
 select jsonb_build_object('estimateId',p_estimate,'revision',coalesce(p.revision,0),'coverTitle',coalesce(p.cover_title,''),'intro',coalesce(p.intro,''),'closing',coalesce(p.closing,''),
  'images',coalesce((select jsonb_agg(jsonb_build_object('id',i.id,'target',i.target,'targetKey',i.target_key,'position',i.position,'source',i.source,'fileId',i.file_id,'caption',i.caption,
     'name',coalesce(public.pro_estimate_proposal_file(p_owner,i.source,i.file_id)->>'name',''),'available',public.pro_estimate_proposal_file(p_owner,i.source,i.file_id) is not null)
    order by case i.target when 'cover' then 0 when 'section' then 1 else 2 end,i.target_key,i.position) from public.pro_estimate_proposal_images i where i.owner_id=p_owner and i.estimate_id=p_estimate),'[]'::jsonb))
 from(select 1) one left join public.pro_estimate_proposals p on p.owner_id=p_owner and p.estimate_id=p_estimate $$;

-- ===== Owner reads =====
create or replace function public.pro_estimate_proposal_read(p_owner uuid,p_query jsonb) returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare v text;keys text[];eid uuid;q text;answer jsonb;
begin
 if jsonb_typeof(p_query) is distinct from 'object' then raise exception 'Invalid proposal query' using errcode='22023';end if;
 v:=p_query->>'view';select array_agg(x order by x) into keys from jsonb_object_keys(p_query) x;
 if keys is distinct from(case v when 'design' then array['estimateId','view'] when 'files' then array['estimateId','query','view'] end) then raise exception 'Unexpected proposal query' using errcode='22023';end if;
 begin eid:=(p_query->>'estimateId')::uuid;exception when others then raise exception 'Invalid identity' using errcode='22023';end;
 perform public.pro_estimate_proposal_owner(p_owner,eid);
 if v='files' then
  q:=lower(btrim(coalesce(p_query->>'query','')));if length(q)>80 then raise exception 'Invalid search' using errcode='22023';end if;
  return jsonb_build_object('items',coalesce((select jsonb_agg(x.j order by x.created desc) from(
   select jsonb_build_object('source','company','fileId',f.id,'name',f.name,'place',null) j,f.created_at as created from public.pro_company_files f where f.owner_id=p_owner and f.mime_type='image/jpeg' and f.ready and not f.archived and(q='' or position(q in lower(f.name))>0)
   union all select jsonb_build_object('source','work','fileId',f.id,'name',f.name,'place',w.service),f.created_at from public.pro_work_files f left join public.pro_work w on w.user_id=f.owner_id and w.id=f.work_id
    where f.owner_id=p_owner and f.mime_type='image/jpeg' and f.ready and(q='' or position(q in lower(f.name||' '||coalesce(w.service,'')))>0)
   order by 2 desc limit 60) x),'[]'::jsonb));
 end if;
 answer:=public.pro_estimate_proposal_json(p_owner,eid)||jsonb_build_object(
  'lines',coalesce((select jsonb_agg(jsonb_build_object('id',i.id,'description',coalesce(i.content->>'description',''),'group',case when jsonb_typeof(i.content->'group')='string' and btrim(i.content->>'group')<>'' then i.content->>'group' end) order by i.position)
   from public.pro_private_estimate_items i where i.owner_id=p_owner and i.estimate_id=eid),'[]'::jsonb),
  'publications',coalesce((select jsonb_agg(jsonb_build_object('publicationId',p.id,'version',p.version,'status',s.status,
    'appliedSeq',(select max(seq) from public.pro_estimate_proposal_snapshots x where x.publication_id=p.id),
    'appliedRevision',(select x.proposal_revision from public.pro_estimate_proposal_snapshots x where x.publication_id=p.id order by x.seq desc limit 1),
    'open',s.status in('awaiting_claim','shared','changes_requested')) order by p.version desc)
   from public.pro_private_estimate_publications p join public.pro_private_estimate_publication_states s on s.publication_id=p.id where p.owner_id=p_owner and p.estimate_id=eid),'[]'::jsonb));
 return answer;
end $$;

-- ===== Owner writes =====
create or replace function public.pro_estimate_proposal_mutate(p_owner uuid,p_input jsonb) returns jsonb language plpgsql security invoker set search_path=public,pg_temp as $$
declare act text;keys text[];aid uuid;eid uuid;receipt public.pro_estimate_proposal_actions;cur integer;before_json jsonb;answer jsonb;img uuid;tgt text;tkey text;src text;fid uuid;pid uuid;
 pub public.pro_private_estimate_publications;st public.pro_private_estimate_publication_states;content jsonb;seqn integer;mv record;other record;
begin
 if jsonb_typeof(p_input) is distinct from 'object' then raise exception 'Invalid proposal action' using errcode='22023';end if;
 act:=p_input->>'action';select array_agg(x order by x) into keys from jsonb_object_keys(p_input) x;
 if keys is distinct from(case act when 'save' then array['action','actionId','closing','coverTitle','estimateId','intro','revision']
  when 'add_image' then array['action','actionId','caption','estimateId','fileId','imageId','revision','source','target','targetKey']
  when 'remove_image' then array['action','actionId','estimateId','imageId','revision']
  when 'move_image' then array['action','actionId','direction','estimateId','imageId','revision']
  when 'publish' then array['action','actionId','estimateId','publicationId','revision'] end)
  or jsonb_typeof(p_input->'revision') is distinct from 'number' or not coalesce(p_input->>'revision'~'^[0-9]{1,10}$',false) or(p_input->>'revision')::numeric>2147483645 then raise exception 'Unexpected proposal fields' using errcode='22023';end if;
 begin aid:=(p_input->>'actionId')::uuid;eid:=(p_input->>'estimateId')::uuid;exception when others then raise exception 'Invalid identity' using errcode='22023';end;
 perform public.pro_estimate_proposal_owner(p_owner,eid);
 perform pg_advisory_xact_lock(hashtextextended('pro-estimate-proposal:'||p_owner::text||':'||eid::text,0));
 select * into receipt from public.pro_estimate_proposal_actions where owner_id=p_owner and action_id=aid;
 if found then if receipt.input is distinct from p_input then raise exception 'Action id reused' using errcode='22023';end if;return receipt.result||jsonb_build_object('replayed',true);end if;
 cur:=coalesce((select revision from public.pro_estimate_proposals where owner_id=p_owner and estimate_id=eid),0);
 if cur<>(p_input->>'revision')::integer then raise exception 'Proposal changed' using errcode='40001';end if;
 before_json:=public.pro_estimate_proposal_json(p_owner,eid);
 if act='save' then
  if jsonb_typeof(p_input->'coverTitle') is distinct from 'string' or jsonb_typeof(p_input->'intro') is distinct from 'string' or jsonb_typeof(p_input->'closing') is distinct from 'string'
   or length(btrim(p_input->>'coverTitle'))>120 or btrim(p_input->>'coverTitle')~'[[:cntrl:]]' or length(p_input->>'intro')>4000 or length(p_input->>'closing')>2000
   or(p_input->>'intro')~'[\x01-\x08\x0b\x0c\x0e-\x1f\x7f]' or(p_input->>'closing')~'[\x01-\x08\x0b\x0c\x0e-\x1f\x7f]' then raise exception 'Invalid proposal text' using errcode='22023';end if;
  insert into public.pro_estimate_proposals(owner_id,estimate_id,revision,cover_title,intro,closing) values(p_owner,eid,cur+1,btrim(p_input->>'coverTitle'),btrim(p_input->>'intro'),btrim(p_input->>'closing'))
  on conflict(owner_id,estimate_id) do update set revision=excluded.revision,cover_title=excluded.cover_title,intro=excluded.intro,closing=excluded.closing,updated_at=clock_timestamp();
 elsif act='add_image' then
  begin img:=(p_input->>'imageId')::uuid;fid:=(p_input->>'fileId')::uuid;exception when others then raise exception 'Invalid identity' using errcode='22023';end;
  tgt:=p_input->>'target';tkey:=coalesce(p_input->>'targetKey','');src:=p_input->>'source';
  if tgt not in('cover','section','line') or src not in('company','work') or jsonb_typeof(p_input->'targetKey') is distinct from 'string' or jsonb_typeof(p_input->'caption') is distinct from 'string'
   or length(btrim(p_input->>'caption'))>160 or btrim(p_input->>'caption')~'[[:cntrl:]]' or(tgt='cover')<>(tkey='') then raise exception 'Invalid proposal photo' using errcode='22023';end if;
  if tgt='line' and not exists(select 1 from public.pro_private_estimate_items i where i.owner_id=p_owner and i.estimate_id=eid and i.id::text=tkey) then raise exception 'Line unavailable' using errcode='P0002';end if;
  if tgt='section' and not exists(select 1 from public.pro_private_estimate_items i where i.owner_id=p_owner and i.estimate_id=eid and btrim(i.content->>'group')<>'' and i.content->>'group'=tkey) then raise exception 'Section unavailable' using errcode='P0002';end if;
  if public.pro_estimate_proposal_file(p_owner,src,fid) is null then raise exception 'Photo unavailable' using errcode='P0002';end if;
  if exists(select 1 from public.pro_estimate_proposal_images where owner_id=p_owner and estimate_id=eid and id=img) then raise exception 'Photo already added' using errcode='23505';end if;
  if(select count(*) from public.pro_estimate_proposal_images where owner_id=p_owner and estimate_id=eid and target=tgt and target_key=tkey)>=(case when tgt='cover' then 1 else 6 end)
   or(select count(*) from public.pro_estimate_proposal_images where owner_id=p_owner and estimate_id=eid)>=60 then raise exception 'Too many photos' using errcode='22023',hint='pro_proposal_photo_limit';end if;
  insert into public.pro_estimate_proposals(owner_id,estimate_id,revision) values(p_owner,eid,cur+1) on conflict(owner_id,estimate_id) do update set revision=excluded.revision,updated_at=clock_timestamp();
  insert into public.pro_estimate_proposal_images(owner_id,estimate_id,id,target,target_key,position,source,file_id,caption)
  values(p_owner,eid,img,tgt,tkey,coalesce((select max(position) from public.pro_estimate_proposal_images where owner_id=p_owner and estimate_id=eid and target=tgt and target_key=tkey),0)+1,src,fid,btrim(p_input->>'caption'));
 elsif act in('remove_image','move_image') then
  begin img:=(p_input->>'imageId')::uuid;exception when others then raise exception 'Invalid identity' using errcode='22023';end;
  select * into mv from public.pro_estimate_proposal_images where owner_id=p_owner and estimate_id=eid and id=img;if mv.id is null then raise exception 'Photo unavailable' using errcode='P0002';end if;
  if act='remove_image' then delete from public.pro_estimate_proposal_images where owner_id=p_owner and estimate_id=eid and id=img;
  else
   if jsonb_typeof(p_input->'direction') is distinct from 'number' or(p_input->>'direction') not in('-1','1') then raise exception 'Invalid direction' using errcode='22023';end if;
   select * into other from public.pro_estimate_proposal_images where owner_id=p_owner and estimate_id=eid and target=mv.target and target_key=mv.target_key
    and case when p_input->>'direction'='1' then position>mv.position else position<mv.position end order by case when p_input->>'direction'='1' then position else -position end limit 1;
   if other.id is null then raise exception 'Nothing to move' using errcode='22023';end if;
   update public.pro_estimate_proposal_images set position=1000 where owner_id=p_owner and estimate_id=eid and id=mv.id;
   update public.pro_estimate_proposal_images set position=mv.position where owner_id=p_owner and estimate_id=eid and id=other.id;
   update public.pro_estimate_proposal_images set position=other.position where owner_id=p_owner and estimate_id=eid and id=mv.id;
  end if;
  update public.pro_estimate_proposals set revision=cur+1,updated_at=clock_timestamp() where owner_id=p_owner and estimate_id=eid;
 else -- publish: freeze the current design on an open shared version of this estimate
  begin pid:=(p_input->>'publicationId')::uuid;exception when others then raise exception 'Invalid identity' using errcode='22023';end;
  select * into pub from public.pro_private_estimate_publications where id=pid and owner_id=p_owner and estimate_id=eid;if pub.id is null then raise exception 'Version unavailable' using errcode='P0002';end if;
  select * into st from public.pro_private_estimate_publication_states where publication_id=pid for update;
  if st.status not in('awaiting_claim','shared','changes_requested') then raise exception 'Version closed' using errcode='40001';end if;
  if cur=0 then raise exception 'Design the proposal first' using errcode='22023';end if;
  content:=jsonb_build_object('coverTitle',(select cover_title from public.pro_estimate_proposals where owner_id=p_owner and estimate_id=eid),
   'intro',(select intro from public.pro_estimate_proposals where owner_id=p_owner and estimate_id=eid),'closing',(select closing from public.pro_estimate_proposals where owner_id=p_owner and estimate_id=eid),
   'images',coalesce((select jsonb_agg(jsonb_build_object('imageId',i.id,'target',i.target,'targetKey',i.target_key,'caption',i.caption,'source',i.source,'fileId',i.file_id)||public.pro_estimate_proposal_file(p_owner,i.source,i.file_id)
     order by case i.target when 'cover' then 0 when 'section' then 1 else 2 end,i.target_key,i.position)
    from public.pro_estimate_proposal_images i where i.owner_id=p_owner and i.estimate_id=eid and public.pro_estimate_proposal_file(p_owner,i.source,i.file_id) is not null
     and(i.target='cover' or i.target='line' and exists(select 1 from jsonb_array_elements(coalesce(pub.content->'lines','[]'::jsonb)) l where l->>'id'=i.target_key)
      or i.target='section' and exists(select 1 from jsonb_array_elements(coalesce(pub.content->'lines','[]'::jsonb)) l where l->>'group'=i.target_key))),'[]'::jsonb));
  seqn:=coalesce((select max(seq) from public.pro_estimate_proposal_snapshots where publication_id=pid),0)+1;
  insert into public.pro_estimate_proposal_snapshots(publication_id,seq,owner_id,proposal_revision,content,content_hash) values(pid,seqn,p_owner,cur,content,encode(sha256(convert_to(content::text,'UTF8')),'hex'));
  answer:=jsonb_build_object('action','publish','revision',cur,'publicationId',pid,'seq',seqn,'proposal',public.pro_estimate_proposal_json(p_owner,eid));
 end if;
 answer:=coalesce(answer,jsonb_build_object('action',act,'revision',cur+1,'proposal',public.pro_estimate_proposal_json(p_owner,eid)));
 insert into public.pro_estimate_proposal_history(owner_id,estimate_id,action_id,action,before_value,after_value) values(p_owner,eid,aid,act,before_json,answer->'proposal'||case when act='publish' then jsonb_build_object('publicationId',pid,'seq',seqn) else '{}'::jsonb end);
 insert into public.pro_estimate_proposal_actions(owner_id,action_id,input,result) values(p_owner,aid,p_input,answer);
 return answer;
end $$;

-- ===== Shared version (owner or recipient) =====
create or replace function public.pro_estimate_proposal_publication_read(p_actor uuid,p_publication uuid) returns jsonb language plpgsql security invoker set search_path=public,pg_temp as $$
declare side text;snap public.pro_estimate_proposal_snapshots;
begin
 side:=public.pro_private_estimate_publication_authorize(p_actor,p_publication,false);
 select * into snap from public.pro_estimate_proposal_snapshots where publication_id=p_publication order by seq desc limit 1;
 if snap.publication_id is null then return jsonb_build_object('publicationId',p_publication,'side',side,'proposal',null);end if;
 return jsonb_build_object('publicationId',p_publication,'side',side,'proposal',jsonb_build_object('seq',snap.seq,'at',snap.at,'coverTitle',snap.content->>'coverTitle','intro',snap.content->>'intro','closing',snap.content->>'closing',
  'images',coalesce((select jsonb_agg(jsonb_build_object('imageId',x->>'imageId','target',x->>'target','targetKey',x->>'targetKey','caption',x->>'caption')) from jsonb_array_elements(snap.content->'images') x),'[]'::jsonb)));
end $$;
create or replace function public.pro_estimate_proposal_image(p_actor uuid,p_publication uuid,p_image uuid) returns jsonb language plpgsql security invoker set search_path=public,pg_temp as $$
declare snap public.pro_estimate_proposal_snapshots;x jsonb;
begin
 perform public.pro_private_estimate_publication_authorize(p_actor,p_publication,false);
 select * into snap from public.pro_estimate_proposal_snapshots where publication_id=p_publication order by seq desc limit 1;
 select e into x from jsonb_array_elements(coalesce(snap.content->'images','[]'::jsonb)) e where e->>'imageId'=p_image::text;
 if x is null then return null;end if;
 return jsonb_build_object('bucket',x->>'bucket','objectPath',x->>'objectPath','sha256',x->>'sha256','sizeBytes',(x->>'sizeBytes')::bigint);
end $$;
-- Owner thumbnails while designing (current file, not a snapshot).
create or replace function public.pro_estimate_proposal_draft_image(p_owner uuid,p_estimate uuid,p_source text,p_file uuid) returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare ref jsonb;
begin
 perform public.pro_estimate_proposal_owner(p_owner,p_estimate);
 if p_source not in('company','work') then raise exception 'Invalid source' using errcode='22023';end if;
 ref:=public.pro_estimate_proposal_file(p_owner,p_source,p_file);if ref is null then return null;end if;
 return jsonb_build_object('bucket',ref->>'bucket','objectPath',ref->>'objectPath','sha256',ref->>'sha256','sizeBytes',(ref->>'sizeBytes')::bigint);
end $$;

do $$declare f record;begin
 for f in select p.oid::regprocedure sig from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in(
  'pro_estimate_proposal_immutable','pro_estimate_proposal_file','pro_estimate_proposal_owner','pro_estimate_proposal_json','pro_estimate_proposal_read','pro_estimate_proposal_mutate',
  'pro_estimate_proposal_publication_read','pro_estimate_proposal_image','pro_estimate_proposal_draft_image') loop
  execute format('revoke all on function %s from public,anon,authenticated',f.sig);execute format('grant execute on function %s to service_role',f.sig);end loop;
end $$;
commit;
notify pgrst,'reload schema';
